(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lt"] = {"ui":{"skip":"Pereiti prie turinio","back":"← Atgal į AI-gile","lang.button":"Kalba: {name}","lang.dialog":"Pasirink kalbą","lang.search":"Ieškoti kalbų","lang.none":"Nėra tokios kalbos","lang.notYet":"{name} dar neišversta","theme.aria":"Perjungti temą: šviesi, tamsi arba juoda","theme.toLight":"Perjungti į šviesią temą","theme.toDark":"Perjungti į tamsią temą","theme.toBlack":"Perjungti į juodą temą (tikra juoda, patogi OLED ekranams)","words.underline":"Pabraukti šiuos žodžius puslapyje","words.underlineHelp":"Užvesk pelę ant taškeliais pabraukto žodžio arba bakstelėk jį, kad pamatytum, ką jis reiškia.","words.col.todo":"Šiuo metu pasirinktos kortelės: komanda prie jų imsis toliau.","words.col.doing":"DI dabar dirba su šia kortele.","words.col.review":"Vienas DI atliko darbą; kitas jį patikrina, kol jis nepasiekė tavęs.","words.col.verify":"Laukia tavęs: išbandyk ir pasakyk, ar veikia.","words.col.team":"Tavo pastabos ar atsakymai, laukiantys, kol komanda juos pasiims.","words.col.done":"Baigta ir priimta.","index.title":"AI-gile: tavo dirbtinio intelekto komanda vienoje lentoje","index.description":"AI-gile yra kanban lenta dirbtinio intelekto programavimo komandoms. Jos dirba, kol tu miegi, o tau lieka vienas trumpas sąrašas: ką nuspręsti, išbandyti ir priimti.","hero.logoAlt":"AI-gile lentos piktograma","hero.h1.html":"Tavo dirbtinio intelekto komanda vienoje&nbsp;lentoje.","hero.alpha":"🐣 Uždara ankstyva alfa","hero.alphaTitle":"Dar nebaigta: ačiū, kad išbandai!","hero.lede":"Jie kuria, kol tu miegi. Pabundi ir randi vieną trumpą krūvelę: keli klausimai, keli dalykai išbandymui, vienas kitas violetinis rombas. Paspaudi, priimi ir grįžti prie kavos.","dl.windows":"Windows programa","dl.browser":"Paleisti naršyklėje","dl.messenger":"📱 Messenger tavo telefonui","dl.soon":"Netrukus","dl.notify":"🔔 Pranešk, kai atsidarys","dl.notifySmall":"Alfa ar beta","hero.secondary":"Agile, bet komandai niekada nereikia rytinės stovimosios kavos. (Susitikimus ji vis tiek rengia.)","pitch.h2":"AI-gile tiek žodžių, kiek nori","pitch.lede":"Pasirink ilgį, nuo vieno žodžio iki 144. Kiekvienas ilgis yra atskiras aprašymas, parašytas būtent tokiam dydžiui. Vilk slankiklį arba spausk rodyklių klavišus.","pitch.rangeLabel":"Ilgis žodžiais","pitch.dice":"🎲 kita versija","pitch.words.one":"{n} žodis","pitch.words.other":"{n} žodžių","pitch.letters.one":"{n} raidė","pitch.letters.other":"{n} raidžių","pitch.chars.one":"{n} simbolis","pitch.chars.other":"{n} simbolių","count.line.html.one":"Šiuo metu lentoje yra {n} kortelė","count.line.html.other":"Šiuo metu lentoje yra {n} kortelių","people.humans.html.one":"👥 {n} žmogus","people.humans.html.other":"👥 {n} žmonės","people.agents.html.one":"🤖 {n} agentas","people.agents.html.other":"🤖 {n} agentai","people.working.html.one":"⚡ {n} šiuo metu dirba","people.working.html.other":"⚡ {n} šiuo metu dirba","pre.title":"AI-gile: čia kažkas kuriama","pre.description":"Čia kažkas kuriama: lenta, kurioje dirbtinio intelekto komandos kuria tai, ko paprašai, ir pakeliui tave moko. Kol kas uždara ankstyva alfa su draugais.","pre.h1":"Čia kažkas kuriama. 🤫","pre.line":"Lenta, kurioje dirbtinio intelekto komandos kuria tai, ko paprašai, ir pakeliui tave moko. Kol kas uždara ankstyva alfa su draugais.","pre.btn":"🔔 Pranešk, kai atsidarys","pre.peek":"Už stiklo: tikra lenta, tiesiogiai. Kiekviena kortelė yra spalvota juostelė.","pre.peekFake":"Už stiklo: taip atrodo dirbanti lenta.","pre.night":"🌙 Nakties sargas viską prižiūri · 😴 žmogus ilsisi","features.aria":"Ką ji daro","f.pile.h":"Viena krūvelė tau","f.pile.html":"<b>Tau</b> kaupia viską, kas laukia tavęs, iš visų projektų: klausimus, dalykus išbandymui, užduotis, kurias gali atlikti tik žmogus. Eilė parodo, kas toliau ir kiek tai užtruks.","f.sleep.h":"Komandos, dirbančios, kol tu miegi","f.sleep.p":"Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok kortelę, ir komanda atsibunda, atlieka darbą ir grąžina jį su žingsniais, kuriuos gali atlikti ir pavargęs žmogus.","f.tester.h":"Pirmiausia tikrina dirbtinio intelekto testuotojas","f.tester.p":"Prieš tau kažką parodant, testuotojas atlieka žingsnius programos kopijoje ir parodo, ką pamatė, su ekrano nuotrauka. Peržvelk išlaikiusius ir priimk vienu paspaudimu.","f.proof.h":"Įrodymai, ne pažadai","f.proof.p":"Kiekvienas perdavimas parodo, kas pasikeitė: failus, skirtumus, ekrano nuotraukas. Nereikia atidarinėti kiekvienos programos, kad sužinotum, ar jau padaryta.","f.chat.h":"Kalbėkis su savo vadovais","f.chat.p":"Kaip Discord: juosta su viena piktograma kiekvienam projektui ir violetiniais rombais tam, kam reikia tavęs. Parašyk vadovui idėją, o jis paverčia ją kortelėmis ir planu su mygtuku ✅ Pirmyn.","f.tidy.h":"Pati susitvarko","f.tidy.p":"Susijusios kortelės sujungiamos į vieną, painūs pavadinimai sutvarkomi, o žetonų patikra palaiko kodą lengvą. Mažiau ką perjunginėti, mažiau ką galvoti.","f.private.h":"Tavo ir tavo kompiuteryje","f.private.li1":"Lenta veikia tavo paties kompiuteryje ir atsako tik tau.","f.private.li2":"Privačios žmonių žinutės šifruojamos nuo galo iki galo.","f.private.li3":"Jokių paskyrų, sekliklių ar slapukų.","f.lang.h":"Tavo kalba","f.lang.p":"Daugiau nei 120 kalbų: nuo olandų, valų ir japonų iki piratų, Yodos ir klingonų, o profesiniam žargonui galima greitai grįžti prie anglų kalbos.","f.service.h":"Nuo idėjos iki tikros paslaugos","f.service.p":"Su AI sukūrei kažką, kuo žmonės dabar naudojasi? Pažymėk tai kaip paslaugą, ir lenta padės ją gerai prižiūrėti: veikimo patikros, viešas būsenos puslapis, incidentai su aprašymu, pakeitimai, kuriems reikia Go, kasdien tikrinamos atsarginės kopijos. Pagalba išmoko kiekvieno žingsnio pakeliui.","msgr.h2":"AI-gile Messenger: tavo komanda kišenėje","msgr.p1":"Kalbėkis su savo AI komanda neatidarydamas lentos. Rašyk projektų vadovams ir draugams, peržiūrėk kortelės testavimo žingsnius ir į juos atsakyk – viskas iš telefono.","msgr.p2":"Norėdamas susieti, nuskenuok QR kodą savo lentoje. Pirmas kartas? Draugiškas demonstracinis pokalbis viską aprodys.","msgr.when":"Pirmiausia Android, po to žiniatinklio versija telefonams ir iPhone.","msgr.who":"Tavo projekto vadovas","msgr.b1":"Tamsaus režimo pataisymas paruoštas. Atsiųsti testavimo žingsnius?","msgr.b2":"Taip, prašau!","msgr.b3":"1. Atidaryk Nustatymus. 2. Pasirink Tamsų. Ar atrodo gerai?","tl.aria":"Laiko juosta nuo pirmo pokalbio iki planų","tl.h2":"Nuo pirmo pokalbio iki to, kas laukia","tl.lede":"Tikros datos ir laikas tavo laiko juostoje. Po šiandien tai tik planas, be pažadėtų datų.","tl.today":"Šiandien","tl.planned":"planuojama","tl.doing":"vykdoma","tl.cards.one":"{n} kortelė","tl.cards.other":"{n} kortelių","join.h2":"Prisijunk","join.lede":"AI-gile kuria barzdotas keistuolis su AuDHD ir keliomis kovomis dėl psichikos sveikatos, ir daugybė kantrių agentų. Kol kas ji uždara: tik uždara alfa su draugais. Nori išbandyti, kai atsivers?","join.btn":"Užsiregistruoti","join.small":"Parašysime el. paštu, ir nieko daugiau","footer.tag":"AI-gile. Jokių sekliklių, jokių slapukų, jokios stovimosios kavos.","footer.licence":"Verslo licencija","footer.status":"Būsena","footer.privacy":"Ką saugome","footer.thanks":"Skambučiai – ChilledChat dėka","form.sending":"Siunčiama…","form.failed":"Nepavyko: pabandyk vėliau.","form.offline":"Nepavyko pasiekti AI-gile: pabandyk vėliau.","form.keep":"Tai naudojame tik tam, kad tau atsakytume, o paskui ištriname. Jokių sekliklių, jokių slapukų.","form.keepLink":"Ką saugome","interest.title":"AI-gile: pranešk man, kai atsidarys alfa","interest.description":"Palik el. paštą, ir sužinosi, kada atsidarys uždara AI-gile alfa ar beta.","interest.h1":"🔔 Pranešk, kai atsidarys","interest.lede":"AI-gile yra uždaroje ankstyvoje alfoje. Palik el. paštą ir parašysime vieną kartą, kai atsiras vieta tau.","interest.email":"Tavo el. paštas","interest.which":"Kuris testas?","interest.alpha":"Uždara alfa: ankstyva, šiurkšti, daug pokyčių","interest.beta":"Beta: stabilesnė, vėliau","interest.both":"Bet kuri, kuri bus pirma","interest.submit":"Įrašykite mane į sąrašą","interest.thanks":"Ačiū! Esi sąraše.","licence.title":"AI-gile: verslo licencija","licence.description":"Naudoji AI-gile savo versle? Paprašyk nemokamos verslo licencijos.","licence.h1":"📜 Verslo licencija","licence.lede":"Naudoji AI-gile darbe? Papasakok, kas esi ir ką veiki. Jei tai daro gero, licencija nemokama.","licence.company":"Įmonė","licence.website":"Svetainė","licence.what":"Ką veiki","licence.how":"Kuo tai padeda pasauliui","licence.email":"El. paštas","licence.submit":"Pateikti","licence.thanks":"Ačiū! Atsakysime el. paštu.","status.title":"AI-gile būsena","status.h1":"AI-gile būsena","status.quiet":"Viskas ramu","status.intro":"Ar AI-gile šiuo metu veikia? Šis puslapis kas 5 minutes tikrina svetainę, lentų bendrinimą, skambučius ir atsisiuntimą.","status.up":"Veikia (atsakė per {ms} ms)","status.slow":"Neatsakė į paskutinį patikrinimą, bandoma iš naujo","status.down":"Neveikia: neatsakė į du paskutinius patikrinimus","status.svc.web":"Svetainė","status.svc.web.offers":"Ši svetainė: kas yra AI-gile, ir susidomėjimo forma","status.svc.boards":"Lentų bendrinimas","status.svc.boards.offers":"Viešos lentos, žinutės tarp draugų ir kvietimai","status.svc.calls":"Skambučiai","status.svc.calls.offers":"Balsas, vaizdas ir ekrano bendrinimas AI-gile","status.svc.download":"Atsisiuntimas","status.svc.download.offers":"„Windows“ diegimo programa ir kvietimų nuorodos","status.checking":"Tikrinama…","status.offline":"Šiuo metu nepavyksta pasiekti būsenos tarnybos (bandoma iš naujo)","status.updated":"atnaujinta {ago}","status.justNow":"ką tik","status.min":"prieš {n} min.","status.hours":"prieš {n} val.","status.days":"prieš {n} d.","privacy.title":"AI-gile: ką saugome","privacy.h1":"Ką saugome","privacy.lede":"Trumpai: tik tai, ką mums atsiunti, ir neilgai.","privacy.only":"Tik tai, ką mums atsiunti: tai, ką įrašai į formą, pavyzdžiui, savo el. paštą. Nieko kito apie tave.","privacy.sealed":"Tai užantspauduojama, kad mūsų serveris negalėtų to perskaityti: tavo naršyklėje, dar prieš išsiunčiant (senesnėje naršyklėje – vos atkeliavus). Atidaryti tai gali tik mūsų pačių lenta.","privacy.server":"Iš serverio tai ištrinama, vos tik pasiekia mūsų lentą. Visa, kas ten dar lieka po 30 dienų, vis tiek ištrinama.","privacy.board":"Savo lentoje tai laikome tik tol, kol tau atsakome, o tada ištriname ir iš ten.","privacy.none":"Jokių sekliklių, jokių slapukų, jokios analitikos.","privacy.local":"Tavo kalba ir šviesaus ar tamsaus režimo pasirinkimas lieka tavo paties naršyklėje. Jie mums niekada nesiunčiami.","privacy.ask":"Nori, kad būtų ištrinta anksčiau? Atsakyk į mūsų laišką ir pasakyk.","live.h2":"Stebėkite, kaip tai kuriama, tiesiogiai","live.caption":"Kiekviena kortelė paslėpta: matote darbo formą, o ne žodžius.","live.watching.one":"tiesiogiai: {n} stebi","live.watching.other":"tiesiogiai: {n} stebi","live.last.now":"Paskutinė kortelė perkelta ką tik","live.last.min.one":"Paskutinė kortelė perkelta prieš {n} min.","live.last.min.other":"Paskutinė kortelė perkelta prieš {n} min.","live.last.hour.one":"Paskutinė kortelė perkelta prieš {n} val.","live.last.hour.other":"Paskutinė kortelė perkelta prieš {n} val.","live.last.day.one":"Paskutinė kortelė perkelta prieš {n} d.","live.last.day.other":"Paskutinė kortelė perkelta prieš {n} d.","live.offline":"Tiesioginė lenta trumpam ilsisi. Užsukite netrukus.","live.cols":"Backlog|Reikia padaryti|Vykdoma|Komanda tikrina|Tau išbandyti|Komandai|Atlikta","pitch.words.few":"{n} žodžiai","pitch.letters.few":"{n} raidės","pitch.chars.few":"{n} simboliai","count.line.html.few":"Šiuo metu lentoje yra {n} kortelės","tl.cards.few":"{n} kortelės"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotai.","Deleguota."]},{"n":2,"texts":["Robotų kanban.","Agentai tvarkomi.","Idėjos įgyvendintos."]},{"n":3,"texts":["Kanban robotams.","Idėjos tampa funkcijomis.","Nemokamas agentų kanban."]},{"n":5,"texts":["Kanban lenta, kurią vairuoja agentai.","Tu rašai korteles. Agentai kuria.","Nemokama, vietinė, išbandyta, kiek kvailoka."]},{"n":8,"texts":["Nemokama kanban lenta, kurioje dirba dirbtinio intelekto agentai.","Užrašai idėją. Agentai ją sukuria. Tu ją priimi.","Agile vienam žmogui ir daugybei labai kantrių robotų."]},{"n":13,"texts":["Kanban lenta tavo kompiuteryje, kurioje kortelių imasi dirbtinio intelekto agentai, o tu čia vyresnysis.","Parašyk idėją. Agentų komanda ją sukuria. Testuotojas patikrina. Tau lieka tik pasakyti taip.","Jokių paskyrų, jokių sekliklių: lenta, keli robotai ir tu, kuris čia viską sprendi."]},{"n":21,"texts":["AI-gile yra kanban lenta darbui su dirbtinio intelekto programavimo agentais. Jie ima korteles, o tu jas išbandai ir priimi.","Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok bet kurią kortelę, ir komanda ima dirbti.","Nemokama asmeninė užduočių lenta, veikianti tavo paties kompiuteryje, be paskyrų. Darbininkai yra robotai. Tas, kuris sako taip, esi tu."]},{"n":34,"texts":["Dedi idėjas į lentą. Dirbtinio intelekto agentų komanda paverčia jas veikiančiomis funkcijomis, išbando ir grąžina su žingsniais, kaip pačiam pabandyti. Niekas nelaikoma padaryta, kol to nepasakai tu.","AI-gile yra namie pagaminta kanban lenta, kurią Richas sukūrė su didele pagalba agentų, kuriuos ji dabar valdo. Ji nemokama, veikia tavo kompiuteryje ir dalijamasi su draugais, o ne parduodama.","Įsivaizduok įprastą kanban lentą su stulpeliais nuo Backlog iki Done, tik kortelių čia imasi dirbtinio intelekto agentai. Jie praneša apie pažangą, užstrigę klausia ir visada laukia tavo nykščio aukštyn."]},{"n":55,"texts":["AI-gile yra kanban lenta, kurioje komandą sudaro dirbtinio intelekto agentai. Kiekvienas projektas turi vadovą, kuris planuoja darbą, ir pagalbininkus, kurie jį atlieka. Kai funkcija paruošta, dirbtinio intelekto testuotojas ją išbando ir padaro ekrano nuotrauką, o tada ji patenka į tavo krūvelę. Priimk ją arba pakomentuok, ir ją perdarys.","Viskas prasidėjo nuo vieno žmogaus noro sekti daugybę dirbtinio intelekto programavimo seansų vienu metu, o išaugo į tikrą lentą. Ji veikia tavo kompiuteryje, nereikalauja paskyros ir neturi sekliklių. Ji nemokama draugams ir smalsuoliams. Ji dar nebaigta, tad tikėkis šiurkštumų ir kartais netikėtumų. Dirbame ją kasdien, po truputį, kartu su draugais, kurie ją bando.","Štai sąžininga versija. Idėjas vis tiek turi sugalvoti pats ir rezultatus vis tiek turi patikrinti pats. AI-gile padaro viską, kas tarp to: laiko korteles tvarkingai, pažadina reikiamą agentą, kai pakomentuoji, parodo, kas tiksliai pasikeitė, ir surenka viską į vieną trumpą krūvelę tau. Tau lieka smagiausia dalis: sugalvoti ir nuspręsti."]},{"n":89,"texts":["AI-gile yra nemokama kanban lenta, kurią paleidi savo kompiuteryje. Vietoj žmonių kiekvienas projektas turi dirbtinio intelekto agentų komandą: vadovą, kuris tavo idėjas paverčia kortelėmis ir planu, ir pagalbininkus, kurie kortelių imasi pagal svarbą. Kai kas nors sukurta, dirbtinio intelekto testuotojas atlieka bandymo žingsnius ir parodo, ką pamatė. Tada viskas laukia vienoje krūvelėje, pavadintoje Tau. Priimi arba pakomentuoji, ir komanda bando dar kartą. Niekas nepasiekia Done be tavęs. Visa tai vyksta tavo kompiuteryje, be paskyrų ir be jokio sekimo.","Kelios funkcijos, kurių galbūt nesitikėjai. Naktinė sargyba papildo stulpelį Ko reikia padaryti, kol tu miegi, rinkdamasi korteles, kurioms nereikia tavo atsakymo. Žetonų skaitiklis rodo, kiek agentai šiandien ir šią savaitę sunaudojo, o No Token Mode liepia jiems nustoti eikvoti. Gali rašyti draugams, o privačios žinutės šifruojamos nuo galo iki galo. Lenta kalba maždaug 120 kalbų, tarp jų olandų, flamandų, piratų ir klingonų. Nė už vieną nereikia mokėti, ir niekas čia tau nieko nebando parduoti. Viskas veikia vietoje, tavo kompiuteryje.","AI-gile yra mažas asmeninis projektas, o ne įmonė. Richas norėjo prižiūrėti kelis dirbtinio intelekto programavimo projektus neatidarinėdamas kiekvienos programos, tad jis su agentais sukūrė tam lentą, o paskui ja pačia sukūrė likusią savęs dalį. Ji yra uždaroje ankstyvoje alfoje, vadinasi, veikia, daugmaž, saujelei draugų. Nėra nei kainų puslapio, nei naujienlaiškio, nei augimo plano. Jei skamba naudinga, gali paprašyti išbandyti, kai ji kiek atsivers. Jokio spaudimo, tik lenta, kuri pamažu tampa geresnė."]},{"n":144,"texts":["AI-gile yra kanban lenta vienam žmogui ir daugybei dirbtinio intelekto agentų. Ji veikia tavo paties kompiuteryje ir yra visiškai nemokama. Pridedi projektus, ir kiekvienas gauna vadovą bei nedidelę komandą. Su vadovu kalbiesi kaip per Discord ir aprašai idėją, o jis paverčia ją kortelėmis ir planu, tada laukia, kol paspausi Pirmyn. Komanda eina per korteles pagal svarbą, naudodama paprastą komandų eilutę, sukurtą kalbos modeliams. Prieš tau ką nors grąžinant, dirbtinio intelekto testuotojas atlieka žingsnius programos kopijoje ir prideda ekrano nuotrauką. Baigtas darbas patenka į tavo krūvelę kartu su pakeistais failais ir skirtumais. Priimi jį arba paliki komentarą, ir komanda pabunda bei bando iš naujo. Kortelę į Done gali perkelti tik tu. Visa tai vyksta tavo kompiuteryje, be paskyrų, be sekliklių ir be slapukų. Ji kalba maždaug 120 kalbų, o draugai gali rašyti vieni kitiems privačiai ir užšifruotai. Ji dar nebaigta, uždara ankstyva alfa, bet jau dabar naudojasi pati savimi.","Maždaug toks AI-gile diena. Vakare palieki kelis komentarus: šis mygtukas ne toje vietoje, tą sąrašą reikia surikiuoti, gal galėtume turėti tamsią temą. Eini miegoti. Agentai perskaito komentarus, padaro pakeitimus, išbando ir grąžina tau. Jei stulpelis Ko reikia padaryti ištuštėja, naktinė sargyba papildo jį iš atsargų kortelėmis, kurioms tavo atsakymo nereikia. Ryte lieka viena trumpa krūvelė: pora klausimų ir keli dalykai išbandymui, kiekvienas su žingsniais, kuriuos gali atlikti ir mieguistas žmogus, bei ekrano nuotrauka, kad veikia. Perbėgi, priimi tinkamus ir grąžini likusius. Žetonų skaitiklis parodo, kiek viskas sunaudojo, o No Token Mode skirtas taupioms savaitėms. Tada pusryčiauji, kuriuose agentai kol kas padėti negali. Naktį lenta dirba už tave, o dieną sprendimus visada priimi tu. Jei kas nors nepavyko, tiesiog parašai komentarą, ir komanda pabunda iš naujo. Taip diena po dienos tavo idėjos keliauja iš minčių į veikiančią programą, o tu nepraleidi vakaro prie kodo.","Pirmiausia, kas AI-gile nėra. Tai ne startuolis, ji neparduodama ir niekas nerenka tavo duomenų. Tai nemokama lenta, veikianti tavo kompiuteryje, be paskyrų, sekliklių ir slapukų. O kas ji yra: viena tvarkinga vieta matyti visus dirbtinio intelekto programavimo projektus iš karto, kur agentų komanda atlieka korteles, o sprendimus priimi tu. Ji sujungia susijusias korteles, sutvarko painius pavadinimus ir stebi, kad kodas liktų lengvas. Ji kalba maždaug 120 kalbų, nuo olandų ir flamandų iki piratų ir klingonų. Draugai gali rašyti vieni kitiems, privačiai ir užšifruotai. Ją sukūrė Richas ir daugybė kantrių agentų, daugiausia naudodamiesi ja pačia. Ji yra uždaroje ankstyvoje alfoje, todėl kai kur šiurkšti. Jei skamba smagiai, paprašyk mandagiai, ir gal pateksi anksti. Mums patinka, kad ji lėta, kantri ir sąžininga: nieko neparduoda, nieko neslepia, tik tvarkingai laiko visus tavo projektus vienoje vietoje."]}],"quips":{"1":"Vienas žodis. Drąsu. Gal net per drąsu.","3":"Trys žodžiai. Jau sąžiningiau nei dauguma produktų puslapių.","8":"Aštuoni žodžiai. Vis tiek trumpiau nei stovimasis susitikimas.","21":"Beje, ilgiai yra istorijos taškai. Žinoma, kad taip.","55":"Penkiasdešimt penki žodžiai. Kol skaitei, baigtos dvi kortelės.","144":"Tai ilgiausia versija. 233 nėra. Agentai nuėjo miegoti."}},"timeline":{"first-idea.name":"Pirmoji idėja","first-idea.line":"Pats pirmas pokalbis, dar nesant nė eilutės kodo.","first-board.name":"Pirmoji lenta","first-board.line":"Lenta, sekanti savo paties kūrimą: kortelės, stulpeliai, tempimas, projektai.","team-roles.name":"Komanda ir vaidmenys","team-roles.line":"Agentų profiliai, komandų šablonai, erdvės ir kas ką daro.","install.name":"Diegimas ir leidimai","install.line":"Zip, kurį gali įsidiegti draugas, savaiminiai atnaujinimai, kanalai ir grąžinimas atgal.","usage-saver.name":"Sąnaudų taupymas","usage-saver.line":"Matuoja, kiek kainuoja paleidimai, laiko kodą lengvą ir taupo tavo limitą.","friends.name":"Draugai ir dalijimasis","friends.line":"Privačios žinutės, užšifruotas relay, kvietimai, vaidmenys ir bendri projektai.","languages.name":"Kalbos","languages.line":"Kiekvienas ekrano tekstas kalbos faile, pirmiausia olandų ir flamandų.","ai-tester.name":"Dirbtinio intelekto testuotojas","ai-tester.line":"Testuotojas pirmas patikrina kiekvieną perdavimą ir parodo, ką pamatė.","website.name":"Svetainė","website.line":"aigile.lol, pristatomasis puslapis ir ši laiko juosta.","streaming.name":"Pokalbiai ir transliacijos","streaming.line":"Discord, Twitch, OBS, transliuotojo režimas, GIF ir jaustukai.","no-ai.name":"Leidimas be dirbtinio intelekto","no-ai.line":"Lenta tiems, kurie programuoja be dirbtinio intelekto, ir vieši projektai.","night-watch.name":"Naktinė sargyba","night-watch.line":"Sargas ir Scrum Master palaiko komandų darbą, kol tu miegi.","p-more.name":"Visa kita","p-more.line":"Mažesnės idėjos, vis dar laukiančios savo eilės.","p-android.name":"Telefonas ir Android","p-android.line":"Pasiek savo lentą iš telefono, vėliau ir iš savos Android programos.","p-release.name":"Alfa ir toliau","p-release.line":"Uždara alfa, gyva svetainė, tada beta.","p-languages.name":"Daugiau kalbų","p-languages.line":"130 kalbų ir kalbos panirimo režimas besimokantiems.","p-engines.name":"Daugiau dirbtinio intelekto variklių","p-engines.line":"Kiekvienam agentui pasirink Claude, Codex, Gemini, Copilot arba Cursor.","p-pro.name":"Profesionali praktika","p-pro.line":"Rizikos žymos, sujungimo vartai, incidentų kortelės ir apsauginiai turėklai.","p-self.name":"Rūpinimasis tavimi","p-self.line":"Pavargimo režimas, priminimai pasirūpinti savimi ir 4:20.","p-servers.name":"Serveriai ir augimas","p-servers.line":"Bendri serverio nustatymai, vaidmenys ir augimo planavimas.","p-livestream.name":"Transliacijų priedai","p-livestream.line":"Twitch pokalbis, savi jaustukai ir vieša gyva peržiūra."},"words":{"button":"📖 Profesinis žargonas","h":"📖 Žodžiai paaiškinti","intro":"Nemokami mokymai paprasta kalba: visi žodžiai, kuriuos sutiksi nuo pirmos idėjos iki paslaugos, kuria žmonės pasikliauja, o pakeliui – Agile, kūrimas, saugumas ir darbas su AI.","search":"Ieškoti žodžio…","none":"Atitinkančių žodžių nėra.","close":"Uždaryti","count":{"one":"{count} žodis","other":"Žodžių: {count}"},"groups":[{"id":"idea","name":"💡 Idėja ir tyrinėjimas"},{"id":"plan","name":"🗺️ Darbo planavimas"},{"id":"agile","name":"🔁 Agile darbo būdai"},{"id":"build","name":"🛠️ Kūrimas"},{"id":"test","name":"🧪 Testavimas ir kokybė"},{"id":"change","name":"🔀 Saugus keitimas"},{"id":"run","name":"🛎️ Paslaugos priežiūra"},{"id":"sec","name":"🔒 Saugumas ir privatumas"},{"id":"ai","name":"🤖 Darbas su AI"},{"id":"money","name":"💰 Pinigai ir licencijos"}],"list":[{"id":"discovery","g":"idea","word":"Poreikių tyrimas","text":"Pradinis etapas, kai dar prieš kuriant aiškinamasi, kokią problemą verta spręsti ir kam.","also":["tyrimo etapas","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problemos apibrėžimas","text":"Vienas ar du sakiniai apie tai, kas patiria problemą, kokia ji ir kodėl svarbi. Taip visi siekia to paties.","also":["problemos apibrėžimai","problem statements"]},{"id":"user","g":"idea","word":"Naudotojas","text":"Žmogus, kuris naudojasi tuo, ką kuri. Darbas skirtas jo poreikiams tenkinti.","also":["naudotojai","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Suinteresuotoji šalis","text":"Visi, kuriems rūpi darbo rezultatas arba kuriuos jis paveikia, pavyzdžiui, mokantys, besinaudojantys ar padedantys prižiūrėti žmonės.","also":["suinteresuotosios šalys","stakeholders"]},{"id":"persona","g":"idea","word":"Naudotojo persona","text":"Išgalvotas, bet tikroviškas žmogus, atstovaujantis vienai naudotojų grupei. Komanda gali klausti: „Ar Samui tai būtų lengva?“","also":["personos","personas"]},{"id":"userresearch","g":"idea","word":"Naudotojų tyrimas","text":"Pokalbiai su tikrais žmonėmis ir jų stebėjimas, kad sužinotum, ko jiems reikia, užuot spėliojus.","also":["pokalbiai su naudotojais","user interviews"]},{"id":"journey","g":"idea","word":"Naudotojo kelionė","text":"Žingsniai, kuriuos žmogus nueina nuo pirmos žinios iki atlikto veiksmo, įskaitant veiksmus už tavo produkto ribų. Juos nubraižius matyti, kur stringama.","also":["naudotojo kelionės","kliento kelionė","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Skaudulys","text":"Tai, kas šiandien žmones erzina ar lėtina. Geri produktai tokius sunkumus pašalina.","also":["skauduliai","pain points"]},{"id":"assumption","g":"idea","word":"Prielaida","text":"Tai, kuo tiki, bet dar nepatikrinai. Užrašius prielaidas matyti, ką tikrinti pirmiausia.","also":["prielaidos","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotezė","text":"Pagrįstas spėjimas, kurį ketini patikrinti, ir laukiamas rezultatas, pavyzdžiui: „Žmonės užsiregistruos, jei pirmas mėnuo bus nemokamas.“","also":["hipotezės","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperimentas","text":"Nedidelis suplanuotas bandymas sužinoti, ar idėja veikia, prieš daug į ją investuojant.","also":["eksperimentai","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Koncepcijos patikrinimas (PoC)","text":"Greitas, apytikris bandymas išsiaiškinti, ar idėja apskritai gali veikti. Gavus atsakymą jo rezultatas paprastai nebenaudojamas.","also":["PoC","proof of concept","koncepcijos patikrinimas"]},{"id":"prototype","g":"idea","word":"Prototipas","text":"Ankstyvas produkto modelis, dažnai paspaudžiami vaizdai. Jis leidžia išbandyti idėją su žmonėmis dar prieš kuriant tikrą produktą.","also":["prototipai","prototypes"]},{"id":"wireframe","g":"idea","word":"Ekrano karkasas","text":"Paprastas ekrano eskizas, rodantis elementų vietas, be spalvų ir tikro turinio.","also":["ekranų karkasai","wireframes"]},{"id":"mockup","g":"idea","word":"Maketas","text":"Išsamus būsimo ekrano vaizdas su tikromis spalvomis ir tekstu, tačiau dar neveikiantis.","also":["maketai","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Projekto pagrindimas","text":"Priežastys imtis projekto: kiek jis kainuos, ką uždirbs ar sutaupys ir kokia rizika.","also":["projekto pagrindimai","business cases"]},{"id":"feasibility","g":"idea","word":"Įgyvendinamumas","text":"Ar turint tiek laiko, pinigų ir įgūdžių iš tikrųjų galima ką nors sukurti ir prižiūrėti.","also":["įgyvendinamas"]},{"id":"outcome","g":"idea","word":"Siekiamas rezultatas","text":"Pokytis, kurio sieki žmonėms, pavyzdžiui, mažiau praleistų susitikimų. Jis svarbesnis už sukurtų dalykų kiekį.","also":["siekiami rezultatai","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Darbo rezultatas","text":"Tai, ką sukuria komanda, pavyzdžiui, naujas ekranas ar ataskaita. Vien sukūrimas dar nereiškia, kad tai kam nors naudinga.","also":["darbo rezultatai","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Sėkmės rodiklis","text":"Skaičius, rodantis, ar darbas pasiekė tikslą, pavyzdžiui, ar daugiau žmonių užbaigia užsakymą.","also":["sėkmės rodikliai","success metrics"]},{"id":"kpi","g":"idea","word":"Pagrindinis veiklos rodiklis (KPI)","text":"Svarbus stebimas skaičius, rodantis, ar sekasi gerai, pavyzdžiui, registracijų skaičius per savaitę.","also":["KPI","KPIs","key performance indicator","pagrindinis veiklos rodiklis"]},{"id":"okr","g":"idea","word":"Tikslai ir pagrindiniai rezultatai (OKR)","text":"Tikslų nustatymo būdas: tikslas nusako, ko nori pasiekti, o keli pagrindiniai rezultatai yra skaičiai, rodantys, kad tai pavyko.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produktas","text":"Naudotojams kuriamas ir prižiūrimas dalykas, pavyzdžiui, programėlė, svetainė ar įrankis.","also":["produktai","products"],"noTip":1},{"id":"vision","g":"plan","word":"Produkto vizija","text":"Trumpas aprašas, kam produktas padeda ir kur ilgainiui juda.","also":["vizijos aprašas","vision statement"]},{"id":"po","g":"plan","word":"Produkto savininkas (PO)","text":"Žmogus, sprendžiantis, ką kurti ir kokia tvarka, kad komanda visada dirbtų prie svarbiausių dalykų. AI-gile tai esi tu.","also":["PO","produkto savininkai","product owners"]},{"id":"pm","g":"plan","word":"Produkto vadovas (PM)","text":"Žmogus, atsakingas už produkto kryptį: kokias problemas jis sprendžia, kam ir kodėl. PM gali reikšti ir projekto vadovą, todėl pasitikrink.","also":["produkto vadovai","product managers"]},{"id":"projmgr","g":"plan","word":"Projekto vadovas","text":"Žmogus, prižiūrintis projekto terminus ir biudžetą bei sekantis, kas ką ir iki kada daro.","also":["projektų vadovai","project managers"]},{"id":"roadmap","g":"plan","word":"Veiksmų planas","text":"Apytikris artimiausių mėnesių darbų planas eilės tvarka. Jis rodo kryptį, o ne tikslias datas, ir keičiasi sužinant daugiau.","also":["veiksmų planai","roadmaps"]},{"id":"milestone","g":"plan","word":"Svarbus etapas","text":"Verta pažymėti projekto akimirka, pavyzdžiui, „pirmoji versija jau veikia“ ar „100 naudotojų“.","also":["svarbūs etapai","milestones"]},{"id":"mvp","g":"plan","word":"Minimalus gyvybingas produktas (MVP)","text":"Mažiausia produkto versija, kuri jau naudinga tikriems žmonėms ir leidžia anksti mokytis iš jų patirties.","also":["MVP","MVPs","minimum viable product","minimalus gyvybingas produktas"]},{"id":"requirement","g":"plan","word":"Reikalavimas","text":"Tai, ką užbaigtas produktas privalo daryti arba kokias savybes turėti.","also":["reikalavimai","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Darbų apimtis","text":"Kas įeina į darbą ir, ne mažiau svarbu, kas neįeina.","also":["įtraukta į apimtį","už apimties ribų","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Apimties plėtimasis","text":"Kai prie darbo vis pridedama naujų dalykų nesusitarus dėl papildomo laiko ar kainos, todėl jis niekaip nesibaigia.","also":["funkcijų plėtimasis","feature creep"]},{"id":"feature","g":"plan","word":"Funkcija","text":"Vienas dalykas, kurį produktas leidžia žmogui padaryti, pavyzdžiui, atkurti slaptažodį.","also":["funkcijos","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epikas","text":"Didelis darbas, kurio nepavyks atlikti vienu kartu, todėl jis skaidomas į mažesnes korteles.","also":["epikai","epics"]},{"id":"story","g":"plan","word":"Naudotojo istorija","text":"Nedidelis darbas, aprašytas naudotojo požiūriu: „Kaip pirkėjas noriu išsaugoti krepšelį, kad galėčiau apsipirkti vėliau.“ Tai pradeda pokalbį apie tai, ką kurti.","also":["naudotojų istorijos","user stories"]},{"id":"ac","g":"plan","word":"Priėmimo kriterijai (AC)","text":"Prieš darbą sutarti patikrinimai, kuriuos kortelė turi atitikti, kad būtų baigta, pavyzdžiui: „Atsijungus ir vėl prisijungus krepšelis išlieka.“","also":["priėmimo kriterijai","acceptance criteria"]},{"id":"task","g":"plan","word":"Užduotis","text":"Vienas atliktinas darbas, dažnai nedidelis didesnės naudotojo istorijos žingsnis.","also":["užduotys","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Darbo įrašas","text":"Kitas kortelės pavadinimas: vienas darbas ar prašymas, stebimas nuo pradžios iki pabaigos.","also":["darbo įrašai","tickets"]},{"id":"priority","g":"plan","word":"Prioritetas","text":"Kiek kas nors svarbu ar skubu, palyginti su kitais darbais, kad svarbiausi būtų atliekami pirmiausia.","also":["prioritetai","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritetų nustatymas","text":"Darbų rikiavimas pagal svarbą. Dažnai taikomas MoSCoW būdas: būtina, reikėtų, galima ir šį kartą nebus.","also":["prioritetų nustatymas","MoSCoW"]},{"id":"estimate","g":"plan","word":"Įvertis","text":"Apytikris spėjimas, kokio dydžio darbas ar kiek jis truks. Tai spėjimas, o ne pažadas.","also":["įverčiai","vertinimas","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Istorijų taškai","text":"Darbo dydžio vertinimas lyginant korteles tarpusavyje, pavyzdžiui, „maždaug dvigubai didesnė“, o ne skaičiuojant valandas. Jie neskirti komandoms lyginti.","also":["istorijos taškas","story point"]},{"id":"tshirt","g":"plan","word":"Vertinimas marškinėlių dydžiais","text":"Darbo dydžio spėjimas naudojant S, M, L ar XL. Greita ir pakankamai tikslu ankstyvam planavimui.","also":["marškinėlių dydžiai","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planavimo pokeris","text":"Vertinimo žaidimas: visi vienu metu parodo dydžio kortelę, o didžiausią ir mažiausią įvertį pasirinkę paaiškina kodėl.","also":["Scrum poker","planavimo pokeris"]},{"id":"dependency","g":"plan","word":"Priklausomybė","text":"Kai vienas darbas negali prasidėti ar baigtis, kol neprasidėjo ar nesibaigė kitas.","also":["priklausomybės","dependencies"]},{"id":"blocker","g":"plan","word":"Kliūtis","text":"Tai, kas šiuo metu trukdo dirbti toliau, pavyzdžiui, negautas atsakymas ar sugedęs įrankis.","also":["kliūtys","blockers"]},{"id":"deadline","g":"plan","word":"Terminas","text":"Data, iki kurios reikia ką nors užbaigti.","also":["terminai","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Perduodamas rezultatas","text":"Konkretus darbo rezultatas, kuris perduodamas, pavyzdžiui, veikiantis puslapis ar ataskaita.","also":["perduodami rezultatai","deliverables"]},{"id":"forecast","g":"plan","word":"Prognozė","text":"Numatymas pagal turimas žinias, kas tikriausiai nutiks, pavyzdžiui, kada bus baigtas darbas.","also":["prognozės","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Rodiklis","text":"Tai, ką matuoji ir stebi laikui bėgant, pavyzdžiui, puslapio lankymus ar klaidos taisymo trukmę.","also":["rodikliai","metrics"]},{"id":"feedback","g":"plan","word":"Grįžtamasis ryšys","text":"Ką žmonės sako apie tavo darbą: gera ir bloga. Anksti ir dažnai jį gauti yra Agile pagrindas.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Dar nesuplanuotų idėjų ir darbų laukimo sąrašas, kuriame svarbiausia viršuje. Darbai nepradedami, kol neperkeliami į stulpelį „Reikia padaryti“."},{"id":"sprint","g":"agile","word":"Sprintas","text":"Trumpas nustatytos trukmės darbo laikotarpis, dažnai savaitė ar dvi ir niekada daugiau nei mėnuo, su tikslu ir sutartu užbaigtinų kortelių rinkiniu.","also":["sprints","sprint","sprintai"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Trumpas kasdienis pasitarimas: ką kiekvienas padarė, ką darys toliau ir kas jam trukdo. Scrum sistemoje jis vadinamas kasdieniu Scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","kasdienis susitikimas"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Darbo būdas, kai kortelės juda per lentos stulpelius, pavyzdžiui, „Reikia padaryti“, „Vykdoma“, „Atlikta“, o komanda riboja vienu metu vykdomų darbų kiekį, kad srautas nesustotų."},{"id":"wip","g":"agile","word":"WIP riba","text":"WIP reiškia vykdomus darbus. WIP riba – didžiausias kortelių skaičius stulpelyje vienu metu, kad komanda užbaigtų pradėtus darbus prieš imdamasi naujų.","also":["WIP","vykdomo darbo riba"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Trumpas komandos kontrolinis sąrašas, ką reiškia „baigta“, pavyzdžiui, išbandyta ir paaiškinta, prieš perduodant kortelę tau. Jo dvynys, Definition of Ready, nurodo, kada kortelė pakankamai aiški, kad būtų galima pradėti.","also":["Definition of Ready","DoD","DoR","parengties apibrėžimas","baigtumo apibrėžimas"]},{"id":"retro","g":"agile","word":"Retro","text":"Reguliarus komandos darbo aptarimas, siekiant sutarti vieną ar du patobulinimus kitam kartui. Tai retrospektyvos trumpinys. AI-gile retro pasiūlo komandos darbo būdo pakeitimą, o tu pasakai „Go“ arba „Dar ne“.","also":["retrospektyva","retrospektyvos"]},{"id":"swarm","g":"agile","word":"Spiečius","text":"Visi susitelkia: daug žmonių atideda kitus darbus ir kartu sprendžia vieną skubią problemą, kol ją pašalina. AI-gile visos komandos padeda vienam projektui, o kiti tuo metu laukia.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrum sistemoje tai žmogus, padedantis komandai gerai dirbti: šalina kliūtis, palaiko susitikimų kryptį ir moko gerų įpročių niekam neįsakinėdamas. AI-gile Lead Scrum Master visuose projektuose pastebi įstrigusias korteles, paragina komandas ir primena tau, kas laukia.","also":["Lead Scrum Master","skramo meistras"]},{"id":"agile","g":"agile","word":"Agile","text":"Darbo būdas mažais žingsniais: po truputį kuri, dažnai rodai tikrus rezultatus, mokaisi iš žmonių atsiliepimų ir keiti planą eigoje, užuot viską suplanavus iš anksto.","also":["Agile development","agile ways of working","lankstus kūrimas"]},{"id":"manifesto","g":"agile","word":"Agile manifestas","text":"Trumpas 2001 metais programų kūrėjų parašytas pareiškimas. Žmonės, veikiantys rezultatai, glaudus bendradarbiavimas su klientais ir prisitaikymas prie pokyčių jame svarbiau už sudėtingus planus ir dokumentus.","also":["Manifesto for Agile Software Development","lankstaus programinės įrangos kūrimo manifestas"]},{"id":"waterfall","g":"agile","word":"Krioklio modelis","text":"Senesnis darbo būdas: viską suplanuoti, tada viską sukurti ir galiausiai ištestuoti, pereinant iš vieno etapo į kitą. Vėlyvi pakeitimai sudėtingi ir brangūs.","also":["waterfall model","krioklio modelis"]},{"id":"iteration","g":"agile","word":"Iteracija","text":"Vienas kūrimo, tikrinimo ir tobulinimo ratas. Agile darbas susideda iš tokių ratų; sprintas yra viena jų rūšių.","also":["iteracijos","iterations"]},{"id":"increment","g":"agile","word":"Produkto prieaugis","text":"Nauja veikianti produkto dalis, pridėta per sprintą ar darbo ratą ir deranti su tuo, kas jau buvo.","also":["prieaugiai","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Populiarus Agile darbo būdas: nedidelė komanda trumpais sprintais siekia tikslo, turi apibrėžtus vaidmenis ir kelis reguliarius susitikimus planuoti, tikrinti ir tobulėti."},{"id":"scrumteam","g":"agile","word":"Scrum komanda","text":"Nedidelė Scrum darbus atliekanti grupė: produkto savininkas, Scrum Master ir kūrėjai.","also":["Scrum komandos","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum renginiai","text":"Reguliarūs Scrum susitikimai: sprinto planavimas, kasdienis Scrum, sprinto apžvalga ir retrospektyva. Daugelis juos vadina ceremonijomis.","also":["ceremonijos","Scrum ceremonies","ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprinto planavimas","text":"Susitikimas sprinto pradžioje, kai komanda sutaria, kodėl sprintas svarbus, kokių kortelių imsis ir nuo ko pradės.","also":["planavimo susitikimas","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprinto tikslas","text":"Vienas sakinys, nusakantis sprinto paskirtį. Smulkios užduotys gali keistis, jei tik pasiekiamas tikslas.","also":["sprinto tikslai","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Dabartiniam sprintui pasirinktos kortelės ir komandos planas joms atlikti.","also":["sprint backlogs","sprinto darbų sąrašas"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Visas surikiuotas sąrašas to, ką būtų galima sukurti produktui; svarbiausia viršuje. Jis nuolat keičiasi sužinant daugiau.","also":["product backlogs","produkto darbų sąrašas"]},{"id":"productgoal","g":"agile","word":"Produkto tikslas","text":"Didesnis rezultatas, kurio siekiama produktu ir kuris padeda komandai pasirinkti kitą darbą.","also":["produkto tikslai","product goals"]},{"id":"refinement","g":"agile","word":"Backlog tikslinimas","text":"Reguliarus backlog peržiūrėjimas: kortelės sutvarkomos, skaidomos, rikiuojamos ir papildomos detalėmis, kad būtų galima jų imtis. Dar vadinama backlog grooming.","also":["backlog grooming","refinement","darbų sąrašo tikslinimas"]},{"id":"sprintreview","g":"agile","word":"Sprinto apžvalga","text":"Susitikimas sprinto pabaigoje, kai komanda parodo, ką baigė, ir išklauso nuomones, kad nuspręstų, ką daryti toliau.","also":["sprinto apžvalgos","sprint reviews"]},{"id":"demo","g":"agile","word":"Demonstracija","text":"Gyvas užbaigto ir veikiančio darbo parodymas žmonėms, kurie jo prašė.","also":["demonstracijos","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Laiko riba","text":"Iš anksto nustatytas laikas veiklai. Jam pasibaigus sustojama, net jei ne viskas baigta.","also":["ribotas laikas","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Komandos sparta","text":"Kiek darbo komanda paprastai užbaigia per sprintą. Tai padeda planuoti kitą sprintą, bet nevertina, kaip sunkiai žmonės dirba.","also":["komandos sparta","team velocity"]},{"id":"capacity","g":"agile","word":"Komandos pajėgumas","text":"Kiek darbo komanda gali imtis per laikotarpį, įvertinus atostogas ir kitus darbus.","noTip":1},{"id":"burndown","g":"agile","word":"Likusių darbų diagrama","text":"Diagrama, rodanti, kaip kasdien mažėja sprinto darbų likutis. Jei linija nekinta, kažkas stringa.","also":["burndown","burn-down chart","likusių darbų diagrama"]},{"id":"burnup","g":"agile","word":"Atliktų darbų diagrama","text":"Diagrama, rodanti, kaip laikui bėgant daugėja atliktų darbų, greta visos suplanuotos apimties. Taip matyti, kada bus pasiektas tikslas.","also":["burnup","burn-up chart","atliktų darbų diagrama"]},{"id":"kanbanboard","g":"agile","word":"Kanban lenta","text":"Pati lenta: kiekvienam darbo etapui skirtas atskiras stulpelis, o kortelės keliauja iš vieno į kitą.","also":["Kanban lentos","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Traukimo sistema","text":"Darbo būdas, kai naujas darbas pradedamas tik atsiradus laisvų pajėgumų, užuot jį užkrovus jau užimtam žmogui.","also":["pull-based","traukimu grįsta sistema"]},{"id":"flow","g":"agile","word":"Darbų srautas","text":"Kaip sklandžiai darbas juda per lentą. Geras srautas reiškia, kad kortelės juda, o ne kaupiasi.","also":["flow of work","darbų srautas"],"noTip":1},{"id":"leadtime","g":"agile","word":"Įvykdymo trukmė","text":"Laikas nuo prašymo ką nors padaryti iki darbo užbaigimo.","also":["įvykdymo trukmės","lead times"]},{"id":"cycletime","g":"agile","word":"Ciklo trukmė","text":"Laikas nuo tikrosios darbo su kortele pradžios iki jo užbaigimo.","also":["ciklo trukmės","cycle times"]},{"id":"throughput","g":"agile","word":"Pralaidumas","text":"Kiek kortelių užbaigiama per savaitę ar kitą nustatytą laiką.","also":["užbaigimo tempas","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Siauroji vieta","text":"Etapas, kuriame darbai kaupiasi ir stabdo visus toliau esančius darbus, tarsi siauras butelio kaklelis.","also":["siaurosios vietos","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Horizontali juosta","text":"Lentos eilė, sujungianti vienos rūšies korteles, pavyzdžiui, skubius ar vienos komandos darbus.","also":["horizontalios juostos","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Darbo būdas, mažinantis švaistymą, tai yra viską, kas nepadeda klientui, ir palaikantis sklandų darbų srautą."},{"id":"waste","g":"agile","word":"Švaistymas","text":"Lean požiūriu tai viskas, kas reikalauja pastangų, bet nepadeda klientui, pavyzdžiui, laukimas, perdarymas ar niekieno nenaudojamų dalykų kūrimas.","noTip":1},{"id":"kaizen","g":"agile","word":"Nuolatinis tobulėjimas","text":"Nuolatinis gerėjimas mažais, reguliariais pokyčiais ir tikrinant, ar jie padėjo. Vienas būdų – retrospektyvos; dar vadinama kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Savarankiškai besiorganizuojanti komanda","text":"Komanda, pati sprendžianti, kaip atlikti darbą, užuot gavusi nurodymus kiekvienam žingsniui.","also":["savarankiška komanda","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Įvairių kompetencijų komanda","text":"Komanda, turinti visus įgūdžius darbui užbaigti, pavyzdžiui, projektavimo, kūrimo ir testavimo.","also":["įvairių kompetencijų","cross-functional"]},{"id":"spike","g":"agile","word":"Trumpas tiriamasis darbas","text":"Trumpas tyrimas su aiškia laiko riba, skirtas atsakyti į klausimą prieš įsipareigojant atlikti tikrąjį darbą.","also":["tiriamieji darbai","spikes"]},{"id":"rework","g":"agile","word":"Perdarymas","text":"Pakartotinis darbo atlikimas, nes pirmą kartą jis nepavyko tinkamai.","also":["perdaryta","reworked"]},{"id":"safe","g":"agile","word":"Agile dideliu mastu (SAFe)","text":"Būdai taikyti Agile daugelyje didelės organizacijos komandų. Gerai žinomas pavyzdys – SAFe, išplėstinė Agile sistema.","also":["scaled Agile","Agile dideliu mastu"]},{"id":"repo","g":"build","word":"Repo","text":"Projekto kodo aplankas su visa pakeitimų įrašų istorija. Jis gali būti tavo kompiuteryje, GitHub arba abiejose vietose.","also":["repository","saugykla"]},{"id":"branch","g":"build","word":"Branch","text":"Atskira darbo kodo šaka, kad pakeitimus būtų galima daryti neliečiant pagrindinės versijos.","also":["branches","šaka","šakos"]},{"id":"commit","g":"build","word":"Commit","text":"Išsaugota kodo momentinė kopija su trumpa pastaba, kas pasikeitė. Prie bet kurios visada gali grįžti.","also":["commits","commit'ai","komitas"]},{"id":"push","g":"build","word":"Push","text":"Išsaugotų pakeitimų įrašų siuntimas iš šio kompiuterio į bendrą kopiją internete, pavyzdžiui, GitHub, kad jie būtų išsaugoti ir prieinami kitiems."},{"id":"merge","g":"build","word":"Merge","text":"Vienos šakos pakeitimų sujungimas su kita, dažniausiai grąžinant juos į pagrindinę versiją."},{"id":"pr","g":"build","word":"Pull request","text":"Prašymas patikrinti šakos pakeitimus ir sujungti juos su pagrindine versija. Kai kurios svetainės tai vadina merge request.","also":["PR","PRs","merge request","sujungimo prašymas"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodo sutvarkymas nekeičiant, ką jis daro: mažesni failai, aiškesni pavadinimai, mažiau pasikartojimų."},{"id":"bug","g":"build","word":"Klaida","text":"Kažkas, kas neveikia taip, kaip turėtų.","also":["bug","bugs","bugai","klaidos"]},{"id":"peerreview","g":"build","word":"Kolegų peržiūra","text":"Antra akių pora: darbą prieš jam pasiekiant tave patikrina kitas žmogus, kad liktų mažiau klaidų. AI-gile kiekvieną kortelę tikrina kitas AI.","also":["kodo peržiūra","code review","peer review"]},{"id":"code","g":"build","word":"Kodas","text":"Užrašytos instrukcijos, nurodančios kompiuteriui, ką daryti. Dar vadinama pirminiu kodu.","also":["pirminis kodas","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programavimo kalba","text":"Kalba kodui rašyti, pavyzdžiui, JavaScript, Python ar Java. Skirtingos kalbos tinka skirtingiems darbams.","also":["programavimo kalbos","programming languages"]},{"id":"developer","g":"build","word":"Programuotojas (dev)","text":"Žmogus, rašantis ir keičiantis kodą. Dar vadinamas programinės įrangos kūrėju ar inžinieriumi.","also":["programuotojai","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Programinė įranga","text":"Kompiuteriuose ir telefonuose veikiančios programos, o ne patys įrenginiai, vadinami aparatine įranga.","noTip":1},{"id":"app","g":"build","word":"Programėlė","text":"Programa, kuria žmonės ką nors atlieka telefone, kompiuteryje ar naršyklėje.","also":["programėlės","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Saityno programėlė","text":"Naršyklėje veikianti programėlė, kurios nereikia diegti.","also":["saityno programėlės","žiniatinklio programa","web apps","web application"]},{"id":"frontend","g":"build","word":"Naudotojui matoma dalis","text":"Programėlės dalis, kurią matai ir spaudi: ekranai, mygtukai ir tekstai, dažnai naršyklėje.","also":["front-end","frontend","sąsajos dalis"]},{"id":"backend","g":"build","word":"Serverio dalis","text":"Užkulisinė programėlės dalis, sauganti duomenis ir atliekanti veiksmus tau ką nors paspaudus, pavyzdžiui, patikrinanti slaptažodį.","also":["back-end","backend","vidinė dalis"]},{"id":"fullstack","g":"build","word":"Visos sistemos kūrimas","text":"Darbas ir su naudotojui matoma, ir su serverio dalimi.","also":["full-stack"]},{"id":"ui","g":"build","word":"Naudotojo sąsaja (UI)","text":"Tai, ką žmogus mato ir naudoja ekrane: išdėstymas, mygtukai, meniu ir tekstas.","also":["UI","user interface","naudotojo sąsaja"]},{"id":"ux","g":"build","word":"Naudotojo patirtis (UX)","text":"Kaip jaučiamasi kuo nors naudojantis: ar lengva, aišku ir malonu, ar painu ir lėta.","also":["UX","user experience","naudotojo patirtis"]},{"id":"accessibility","g":"build","word":"Prieinamumas (a11y)","text":"Kūrimas taip, kad naudotis galėtų visi, taip pat prasčiau matantys, negalintys naudotis pele ar naudojantys ekrano skaitytuvą.","also":["a11y","prieinamumas"]},{"id":"responsive","g":"build","word":"Prisitaikantis dizainas","text":"Puslapių kūrimas taip, kad jie tiktų ir gerai veiktų bet kokio dydžio ekrane – nuo telefono iki didelio monitoriaus."},{"id":"designsys","g":"build","word":"Dizaino sistema","text":"Bendras spalvų, šriftų, mygtukų ir taisyklių rinkinys, kad visi ekranai atrodytų ir veiktų nuosekliai.","also":["dizaino sistemos","design systems"]},{"id":"architecture","g":"build","word":"Architektūra","text":"Bendra sistemos sandara: pagrindinės dalys ir jų tarpusavio ryšiai."},{"id":"database","g":"build","word":"Duomenų bazė (DB)","text":"Sutvarkyta informacijos saugykla, tarsi labai galinga skaičiuoklė, kurią programėlė gali skaityti ir keisti.","also":["duomenų bazė","duomenų bazės","database","databases","DB"]},{"id":"schema","g":"build","word":"Duomenų bazės schema","text":"Duomenų bazės sandara: kokios joje yra informacijos lentelės ir kas kiekvienoje laikoma.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Struktūrinių užklausų kalbos santrumpa. Ja iš daugelio duomenų bazių gaunama arba keičiama informacija.","also":["Structured Query Language","struktūrinių užklausų kalba"]},{"id":"data","g":"build","word":"Duomenys","text":"Kompiuteryje saugoma informacija, pavyzdžiui, vardai, užsakymai ar nuostatos.","also":["duomenų rinkinys","duomenų rinkiniai","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Serveris","text":"Nuolat veikiantis kompiuteris, atsakantis į kitų kompiuterių užklausas, pavyzdžiui, atsiunčiantis lankomą tinklalapį.","also":["serveriai","servers"]},{"id":"client","g":"build","word":"Klientas","text":"Kažko prašanti pusė, dažniausiai tavo naršyklė ar programėlė, bendraujanti su serveriu. Versle šis žodis reiškia ir pirkėją.","also":["klientai","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Programų sąsajos santrumpa: nustatytas užklausų, kurias viena programa gali pateikti kitai, sąrašas, pavyzdžiui, paprašyti orų tarnybos šiandienos prognozės.","also":["APIs","application programming interface","programų sąsaja"]},{"id":"endpoint","g":"build","word":"API adresas","text":"Vienas API sąrašo punktas: interneto adresas, į kurį programa kreipiasi norėdama ką nors gauti ar nusiųsti.","also":["API adresai","endpoints"]},{"id":"integration","g":"build","word":"Integracija","text":"Dviejų sistemų sujungimas bendram darbui, pavyzdžiui, kai parduotuvė siunčia užsakymus apskaitos programai.","also":["integracijos","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Pranešimas, kurį viena sistema pati nusiunčia kitai vos įvykus įvykiui, pavyzdžiui, „gautas mokėjimas“.","also":["webhooks"]},{"id":"library","g":"build","word":"Biblioteka","text":"Kito žmogaus jau parašytas kodas, kurį gali panaudoti, o ne rašyti viską iš naujo.","also":["bibliotekos","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Programavimo karkasas","text":"Paruošta programėlės kūrimo struktūra, nustatanti didelę dalį kodo išdėstymo, tarsi namo karkasas, kurį užpildai.","also":["karkasai","frameworks"]},{"id":"sdk","g":"build","word":"Programinės įrangos kūrimo rinkinys (SDK)","text":"Įrankių, kodo ir pavyzdžių rinkinys programoms konkrečiai platformai ar paslaugai kurti.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Programinė priklausomybė","text":"Biblioteka ar įrankis, kurio reikia tavo kodui veikti. Saugumui svarbu juos atnaujinti.","also":["programinės priklausomybės","software dependencies"]},{"id":"package","g":"build","word":"Paketas","text":"Paruošto kodo rinkinys, kurį gali įdiegti ir naudoti projekte.","also":["paketai","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Paketų tvarkyklė","text":"Įrankis, parsiunčiantis ir atnaujinantis tavo kodui reikalingus paketus. Dažnas pavyzdys – npm.","also":["paketų tvarkyklės","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Plačiausiai naudojamas įrankis kodo pakeitimų istorijai saugoti, kaip commit'ai ir šakos."},{"id":"github","g":"build","word":"GitHub","text":"Svetainė Git saugykloms laikyti internete, kad komandos galėtų dalytis kodu, peržiūrėti pakeitimus ir sekti darbus."},{"id":"vcs","g":"build","word":"Versijų valdymas","text":"Visos failų pakeitimų istorijos saugojimas, kad matytum, kas ką pakeitė, ir prireikus grįžtum atgal. Tai daro Git.","also":["source control","version control system","versijų valdymo sistema"]},{"id":"clone","g":"build","word":"Klonavimas","text":"Visos saugyklos kopijos su istorija sukūrimas savo kompiuteryje.","also":["klonuota","cloned","cloning"]},{"id":"pull","g":"build","word":"Pakeitimų parsiuntimas","text":"Naujausių commit'ų parsiuntimas iš bendros kopijos, pavyzdžiui, GitHub, į tavo kompiuterį. Priešingas veiksmas – push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Pagrindinė šaka","text":"Oficiali kodo versija, nuo kurios visi pradeda dirbti, dažnai vadinama main arba master.","also":["master branch","pagrindinė šaka"]},{"id":"conflict","g":"build","word":"Sujungimo konfliktas","text":"Kai du pakeitimai tas pačias eilutes keičia skirtingai ir kompiuteris negali jų sujungti, todėl turi nuspręsti žmogus.","also":["sujungimo konfliktai","merge conflicts"]},{"id":"diff","g":"build","word":"Skirtumų rodinys","text":"Rodinys, tiksliai parodantis, kas pasikeitė tarp dviejų versijų: pridėtas ir pašalintas eilutes.","also":["diffs"]},{"id":"fork","g":"build","word":"Saugyklos atšaka","text":"Tavo paties kopija, padaryta iš kito žmogaus saugyklos. Ją gali keisti, o originalas lieka nepaliestas.","also":["atšakos","forks","forked"]},{"id":"script","g":"build","word":"Scenarijus","text":"Trumpa programa, pati atliekanti vieną darbą, pavyzdžiui, sutvarkanti failus ar paleidžianti programėlę.","also":["scenarijai","scripts"],"noTip":1},{"id":"build","g":"build","word":"Surinkimas","text":"Kodo pavertimas paruošta paleisti programa arba pats paruoštas rezultatas.","also":["surinktos versijos","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompiliavimas","text":"Žmonių parašyto kodo vertimas į formą, kurią kompiuteris gali vykdyti tiesiogiai.","also":["kompiliuota","kompiliatorius","compiler"]},{"id":"cli","g":"build","word":"Komandų eilutė (CLI)","text":"Teksto langas, kuriame kompiuteriui rašai komandas, o ne spaudi pele. Dar vadinamas terminalu.","also":["command line","command-line","CLI","terminal","terminalas"]},{"id":"config","g":"build","word":"Konfigūracija","text":"Programos elgseną valdančios nuostatos, laikomos atskirai nuo kodo, kad būtų lengva jas keisti.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Aplinkos kintamasis","text":"Programai paleidimo metu perduodama nuostata, dažnai adresas ar slaptažodis, kad jų nereikėtų rašyti kode.","also":["aplinkos kintamieji","environment variables","env var"]},{"id":"debugging","g":"build","word":"Klaidų derinimas","text":"Aiškinimasis, kodėl kas nors neveikia, ir taisymas.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Porinis programavimas","text":"Du žmonės arba žmogus ir AI kartu dirba su tuo pačiu kodu: vienas rašo, kitas tikrina.","also":["pairing","programavimas poromis"]},{"id":"docs","g":"build","word":"Dokumentacija","text":"Rašytiniai paaiškinimai, kaip kas nors veikia arba kaip tuo naudotis.","also":["documentation","docs","dokumentacija"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Pirmasis saugyklos failas, kurį verta perskaityti: kas tai per projektas ir kaip jį paleisti.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Senoji sistema","text":"Vis dar naudojama sena sistema, kurią sunku keisti, dažnai todėl, kad mažai kas ją dar supranta.","also":["senosios sistemos","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Techninė skola","text":"Trumpesni keliai, kurie dabar sutaupo laiko, bet apsunkina vėlesnius pakeitimus, tarsi paskola su augančiomis palūkanomis. Kodo pertvarkymas ją mažina.","also":["tech debt","techninė skola"]},{"id":"test","g":"test","word":"Testas","text":"Patikrinimas, ar kas nors veikia taip, kaip turėtų. Vienus testus kompiuteris atlieka pats kaskart pakeitus kodą, kitus atlieki tu: išbandai užbaigtą kortelę prieš ją priimant.","also":["test","tests","testai"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kokybės užtikrinimo santrumpa: viskas, kas daroma, kad darbas būtų tinkamas prieš pateikiant naudotojams. AI-gile tai automatiniai patikrinimai: kai QA raudona, kažkas nepavyko ir negalima diegti, kol tai nepataisyta.","also":["kokybės patikra","kokybės užtikrinimas"]},{"id":"testpile","g":"test","word":"Testų krūva","text":"Baigtos kortelės, laukiančios, kol tu jas išbandysi, viena po kitos. Priimk vieną arba grąžink su pastaba, ir pasirodys kita.","also":["testų krūvos","test pile"]},{"id":"autotest","g":"test","word":"Automatinis testas","text":"Patikrinimas, kurį kompiuteris pats atlieka kaskart pakeitus kodą, kad klaidos būtų pastebėtos anksti.","also":["automatiniai testai","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Rankinis testas","text":"Žmogus pats išbando darbą ir tikrina, ar jis veikia kaip numatyta.","also":["rankiniai testai","rankinis testavimas","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Vienetinis testas","text":"Nedidelis automatinis patikrinimas, tikrinantis vieną mažą kodo dalį atskirai.","also":["vienetiniai testai","unit tests"]},{"id":"integtest","g":"test","word":"Integracinis testas","text":"Patikrinimas, ar kelios dalys tinkamai veikia kartu, o ne tik kiekviena atskirai.","also":["integraciniai testai","integration tests"]},{"id":"endtoend","g":"test","word":"Viso proceso testas (E2E)","text":"Testas, imituojantis tikrą naudotoją nuo pradžios iki pabaigos, pavyzdžiui, registraciją, pirkimą ir mokėjimą.","also":["E2E","end-to-end tests","viso proceso testai"]},{"id":"uat","g":"test","word":"Naudotojų priėmimo testavimas (UAT)","text":"Darbo prašę žmonės patys jį išbando ir pasako, ar jis atitinka jų poreikius. AI-gile testų krūva yra šio proceso atitikmuo.","also":["UAT","acceptance testing","priėmimo testavimas"]},{"id":"regression","g":"test","word":"Regresija","text":"Tai, kas veikė, bet po pakeitimo sugedo. Regresiniai testai tikrina, ar ankstesnės funkcijos vis dar veikia.","also":["regresijos","regression test","regression tests","regression testing","regresinis testavimas"]},{"id":"smoke","g":"test","word":"Pagrindinių funkcijų testas","text":"Labai greitas patikrinimas, ar pagrindiniai dalykai apskritai veikia, pavyzdžiui, iškart įdiegus pakeitimą. Jei nepavyksta, sustok ir patikrink.","also":["smoke tests","pirminiai testai"]},{"id":"exploratory","g":"test","word":"Tiriamasis testavimas","text":"Laisvas produkto bandymas įvairiais būdais, ieškant problemų, kurių suplanuoti patikrinimai nepastebėtų.","also":["exploratory test","exploratory tests","tiriamieji testai"]},{"id":"testcase","g":"test","word":"Testavimo atvejis","text":"Vienas užrašytas bandymo scenarijus: veiksmai ir laukiamas rezultatas.","also":["testavimo atvejai","test cases"]},{"id":"coverage","g":"test","word":"Testų aprėptis","text":"Kokia kodo dalis patikrinama automatiniais testais. Didesnė aprėptis paprastai saugesnė, bet pati savaime neįrodo, kad viskas veikia gerai.","also":["code coverage","kodo aprėptis"]},{"id":"testdata","g":"test","word":"Testavimo duomenys","text":"Testavimui naudojama išgalvota pavyzdinė informacija, kad nebūtų atskleisti tikrų žmonių asmens duomenys.","also":["test fixtures","bandomieji duomenys"]},{"id":"edgecase","g":"test","word":"Ribinis atvejis","text":"Neįprasta situacija ties galimybių riba, pavyzdžiui, tuščia forma ar vardas su apostrofu, kai dažnai kas nors sugenda.","also":["ribiniai atvejai","edge cases"]},{"id":"happypath","g":"test","word":"Sklandus scenarijus","text":"Įprastas kelias, kai viskas pavyksta. Geras testavimas apima ir nesėkmių scenarijus."},{"id":"perftest","g":"test","word":"Našumo testavimas","text":"Tikrinimas, kaip greitai kas nors veikia ir kaip susidoroja su didesne apkrova.","also":["performance test","performance tests","našumo testai"]},{"id":"loadtest","g":"test","word":"Apkrovos testavimas","text":"Tikrinimas, kaip sistema susidoroja, kai ja vienu metu naudojasi daug žmonių.","also":["load test","load tests","apkrovos testai"]},{"id":"sectest","g":"test","word":"Saugumo testavimas","text":"Silpnų vietų, leidžiančių piktnaudžiauti sistema ar pamatyti neleistiną informaciją, paieška.","also":["security test","security tests","saugumo testai"]},{"id":"accesstest","g":"test","word":"Prieinamumo testavimas","text":"Tikrinimas, ar produktu gali naudotis skirtingų gebėjimų žmonės, taip pat su ekrano skaitytuvu ar vien klaviatūra.","also":["accessibility test","prieinamumo testas"]},{"id":"linting","g":"test","word":"Kodo tvarkingumo tikrinimas","text":"Automatinis tikrinimas, aptinkantis tikėtinas kodo klaidas ir netvarkingą stilių, tarsi programų rašybos tikrintuvas.","also":["linter","lint","kodo tikrintuvas"]},{"id":"static","g":"test","word":"Statinė analizė","text":"Automatinis kodo skaitymas ieškant problemų, jo nepaleidžiant.","also":["static code analysis","statinė kodo analizė"]},{"id":"flaky","g":"test","word":"Nepastovus testas","text":"Testas, kuris be aiškios priežasties tai pavyksta, tai nepavyksta, todėl juo negalima visiškai pasitikėti.","also":["nepastovūs testai","flaky tests"]},{"id":"repro","g":"test","word":"Klaidos atkūrimas","text":"Tyčinis klaidos pakartojimas tais pačiais veiksmais, kad būtų galima ją ištirti ir pataisyti. Šių žingsnių aprašymas – naudingiausia pranešimo apie klaidą dalis.","also":["repro","reproduce","steps to reproduce","atkūrimo žingsniai"]},{"id":"severity","g":"test","word":"Sunkumas","text":"Kokio masto problemos poveikis: nuo menko nepatogumo iki visiško veiklos sustojimo.","also":["severity level","sunkumo lygis"]},{"id":"deploy","g":"change","word":"Deploy","text":"Naujos programos versijos nukopijavimas į kompiuterius, kuriuose ji veikia, pavyzdžiui, į testavimo kopiją ar tikrąją paslaugą."},{"id":"release","g":"change","word":"Leidimas","text":"Pavadintas baigto darbo paketas, kuris paleidžiamas gyvai kartu, su trumpomis pastabomis, kas pasikeitė. 🚀 Leidimai pastabas parašo iš atliktų kortelių.","also":["leidimai","release"]},{"id":"rollback","g":"change","word":"Atsukti atgal","text":"Grįžimas prie paskutinės veikusios versijos, kai nauja sukelia problemų. AI-gile veiksmas „Atsukti atgal“ surenka prie kiekvieno pakeitimo aprašytus atšaukimo žingsnius į vieną kontrolinį sąrašą.","also":["rollback","atsukimas atgal","atšaukimas"]},{"id":"live","g":"change","word":"Gyvai","text":"Tikroji versija, kuria žmonės naudojasi, o ne kopija bandymams. Programuotojai ją dar vadina produkcija (production).","also":["gyva aplinka","produkcija","production"],"noTip":1},{"id":"change","g":"change","word":"Pakeitimas","text":"Suplanuotas pakeitimas to, kuo žmonės pasikliauja, iš anksto užrašytas: kas, kodėl, rizika, kada ir kaip jį atšaukti. Pradėk mygtuku 🔀 Pateikti pakeitimą.","also":["pakeitimai","pakeitimo užklausa"],"noTip":1},{"id":"risk","g":"change","word":"Rizika","text":"Kažkas, kas gali nepavykti, įvertinta pagal tai, kiek tai tikėtina ir kiek blogai būtų. ⚠️ Rizikos laiko jas viename sąraše, nuo didžiausio balo, kiekviena su data, kada pažiūrėti dar kartą.","also":["rizikos","rizikų registras"]},{"id":"chgwin","g":"change","word":"Pakeitimų langas","text":"Laikas, kai pakeitimus galima paleisti gyvai, pavyzdžiui, ramus antradienio vakaras. Už lango ribų pakeitimo kortelės užbaigti negalima, nebent tai skubus atvejis.","also":["pakeitimų langai","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Paskutinis patikrinimas prieš diegiant pakeitimą: kiekvienas tvirtinantis žmogus pasako „Go“ arba „No go“. Darbas tęsiamas tik visiems pasakius „Go“.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Patvirtinimas","text":"„Taip“ laukimas prieš pradedant darbą. Draugo pateikta kortelė arba pakeitimas laukia skiltyje ✅ Patvirtinimai, kol tu jį patvirtinsi arba atmesi.","also":["patvirtinimai"]},{"id":"quiettime","g":"change","word":"Ramybės laikas","text":"Laikotarpis, pavyzdžiui, tiesioginė transliacija, demonstracija ar naktis, kai jokie pakeitimai nediegiami naudotojams. Komandos toliau dirba ir testuoja, bet diegimas laukia laikotarpio pabaigos; kitur tai vadinama pakeitimų įšaldymu.","also":["ramybės laikai","pakeitimų įšaldymas","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Darbo būdas, kai programų kūrėjai ir prižiūrėtojai dirba kaip viena komanda ir daug ką automatizuoja, kad pakeitimai būtų dažnai ir saugiai pateikiami naudotojams."},{"id":"cicd","g":"change","word":"CI/CD (nuolatinis integravimas ir pateikimas)","text":"Visų pakeitimai dažnai sujungiami į pagrindinę versiją ir kaskart automatiškai tikrinami (nuolatinis integravimas), todėl programa visada paruošta pateikti naudotojams vienu mygtuko paspaudimu (nuolatinis pateikimas).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","nuolatinis integravimas","nuolatinis pateikimas"]},{"id":"contdeploy","g":"change","word":"Nuolatinis diegimas","text":"Žingsnis toliau už nuolatinį pateikimą: kiekvienas patikrinimus įveikęs pakeitimas įdiegiamas automatiškai, nespaudžiant jokio mygtuko.","also":["continuous deployments","nuolatiniai diegimai"]},{"id":"pipeline","g":"change","word":"Automatinių veiksmų seka","text":"Automatinė žingsnių seka, kurią pakeitimas pereina iki pateikimo naudotojams, pavyzdžiui, surinkimas, testavimas ir diegimas.","also":["pipelines","veiksmų sekos"]},{"id":"environment","g":"change","word":"Aplinka","text":"Atskira sistemos kopija konkrečiam tikslui, pavyzdžiui, kūrimui, testavimui ar tikram naudojimui.","also":["aplinkos","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Kūrimo aplinka","text":"Kopija, kurioje dirba programuotojas, dažnai savo kompiuteryje, ir kurioje ką nors sugadinus niekas nenukenčia.","also":["dev environment","kūrimo aplinka"]},{"id":"testenv","g":"change","word":"Testavimo aplinka","text":"Atskira sistemos kopija, skirta tik testavimui, kad nebūtų paveikta tikroji paslauga.","also":["test environments","testavimo aplinkos"]},{"id":"staging","g":"change","word":"Priešgamybinė aplinka","text":"Paskutinė kopija, paruošta kaip tikroji sistema, galutiniam patikrinimui prieš diegiant pakeitimą naudotojams.","also":["staging environment","priešgamybinė aplinka"]},{"id":"artifact","g":"change","word":"Surinkimo artefaktas","text":"Surinkimo metu sukurtas failas ar rinkinys, paruoštas saugoti, tikrinti ar diegti.","also":["build artifacts","surinkimo artefaktai"]},{"id":"hotfix","g":"change","word":"Skubus pataisymas","text":"Skubus pataisymas, greitai įdiegiamas ne pagal įprastą planą, nes sugedo kas nors svarbaus.","also":["hotfixes","skubūs pataisymai"]},{"id":"patch","g":"change","word":"Pataisa","text":"Nedidelis atnaujinimas, ištaisantis klaidą ar užtaisantis saugumo spragą. Saugumo pataisas svarbu diegti greitai.","also":["patches","security patch","security patches","saugumo pataisos"]},{"id":"version","g":"change","word":"Versijos numeris","text":"Žyma, pavyzdžiui, 2.4.1, nurodanti turimą leidimą. Dažnai pirmas skaičius keičiamas dideliems pakeitimams, o paskutinis – smulkioms pataisoms.","also":["version numbers","semantic versioning","versijų numeriai","semantinis versijavimas"]},{"id":"relnotes","g":"change","word":"Leidimo pastabos","text":"Trumpas, aiškus leidimo pakeitimų sąrašas naudotojams, įskaitant pataisas ir žinomus apribojimus. Dar vadinamas pakeitimų žurnalu.","also":["changelog","change log","pakeitimų žurnalas"]},{"id":"flag","g":"change","word":"Funkcijos jungiklis","text":"Funkcijos įjungimo ir išjungimo jungiklis. Jis leidžia įdiegti paslėptą naujovę ir ją įjungti ar išjungti be naujo leidimo.","also":["feature flags","feature toggle","feature toggles","funkcijų jungikliai"]},{"id":"rollfwd","g":"change","word":"Taisymas nauja versija","text":"Nesėkmingo leidimo taisymas greitai išleidžiant naują pataisytą versiją, užuot grįžus prie senos.","also":["rolling forward","rolled forward","taisymas nauja versija"]},{"id":"canary","g":"change","word":"Bandomasis leidimas","text":"Pakeitimas iš pradžių pateikiamas mažai grupei ir tik įsitikinus, kad viskas gerai, visiems. Pavadinimas kilo iš šachtininkų neštų kanarėlių, kurios iš anksto įspėdavo apie pavojų.","also":["canary releases","canary","bandomieji leidimai"]},{"id":"bluegreen","g":"change","word":"Mėlynasis ir žaliasis diegimas","text":"Laikomos dvi veikiančios sistemos kopijos, o naudotojai vienu kartu perjungiami į naująją. Jei kas nors negerai, galima iškart grįžti.","also":["blue-green","blue green deployment","mėlynasis ir žaliasis diegimas"]},{"id":"zerodown","g":"change","word":"Diegimas be prastovos","text":"Naujos versijos diegimas nė akimirkai nesustabdant paslaugos naudotojams.","also":["zero downtime","zero-downtime","be prastovos"]},{"id":"chgenable","g":"change","word":"Pakeitimų įgyvendinimo valdymas","text":"Pagalba sėkmingai įgyvendinti pakeitimus: rizikos įvertinimas, reikiamas patvirtinimas ir tinkamas laikas. Dar vadinama pakeitimų valdymu.","also":["change management","pakeitimų valdymas"]},{"id":"cab","g":"change","word":"Pakeitimų patariamoji taryba (CAB)","text":"Grupė, peržiūrinti svarbius pakeitimus ir sutarianti, ar ir kada juos galima atlikti.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standartinis pakeitimas","text":"Mažos rizikos pakeitimas, kiekvieną kartą atliekamas tuo pačiu patikrintu būdu, todėl patvirtintas iš anksto.","also":["standard changes","standartiniai pakeitimai"]},{"id":"normchange","g":"change","word":"Įprastas pakeitimas","text":"Pakeitimas, kurį prieš atliekant reikia patikrinti ir patvirtinti.","also":["normal changes","įprasti pakeitimai"]},{"id":"emergchange","g":"change","word":"Avarinis pakeitimas","text":"Pakeitimas, kurį būtina atlikti iškart norint pašalinti ar išvengti didelės bėdos, todėl jis patvirtinamas greičiau.","also":["emergency changes","avariniai pakeitimai"]},{"id":"automation","g":"change","word":"Automatizavimas","text":"Pasikartojančio darbo perdavimas kompiuteriui, kad jis būtų atliekamas greičiau ir kiekvieną kartą vienodai.","also":["automated","automatizuota"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktūra","text":"Įrenginiai, tinklai ir paslaugos, kuriose veikia programinė įranga.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastruktūra kaip kodas (IaC)","text":"Serverių ir nuostatų aprašymas kartu su kodu saugomuose failuose, kad kaskart būtų galima atkurti tokią pačią aplinką.","also":["IaC"]},{"id":"cloud","g":"change","word":"Debesija","text":"Kompiuterių, saugyklų ir paslaugų nuoma internetu iš didelio tiekėjo, užuot turėjus savo įrenginius.","also":["the cloud","cloud computing","debesų kompiuterija"]},{"id":"provider","g":"change","word":"Debesijos tiekėjas","text":"Įmonė, internetu nuomojanti kompiuterinius išteklius, pavyzdžiui, Amazon Web Services (AWS), Microsoft Azure ar Google Cloud.","also":["cloud providers","debesijos tiekėjai"]},{"id":"hosting","g":"change","word":"Priegloba","text":"Vieta, kur laikoma ir veikia tavo programėlė ar svetainė, kad žmonės galėtų ją pasiekti. Paprastai nuomojama iš įmonės.","also":["talpinimas"]},{"id":"domain","g":"change","word":"Domeno vardas","text":"Žmonių įvedamas interneto vardas, pavyzdžiui, example.com. Jis nuomojamas metams, todėl nuomą reikia pratęsti.","also":["domain names","domain","domenas","domenų vardai"]},{"id":"dns","g":"change","word":"DNS","text":"Domenų vardų sistemos santrumpa: interneto adresų knyga, paverčianti vardą, pavyzdžiui, example.com, reikiamo kompiuterio adresu.","also":["domain name system","domenų vardų sistema"]},{"id":"container","g":"change","word":"Konteineris","text":"Uždaras paketas su programėle ir viskuo, ko jai reikia, kad bet kuriame kompiuteryje veiktų vienodai. Geriausiai žinomas įrankis – Docker.","also":["containers","Docker","konteineriai"],"noTip":1},{"id":"vm","g":"change","word":"Virtualioji mašina (VM)","text":"Tariamas kompiuteris, veikiantis tikrame kompiuteryje, kad vienas didelis įrenginys galėtų atstoti daugelį.","also":["VM","VMs","virtual machines","virtualiosios mašinos"]},{"id":"serverless","g":"change","word":"Serverless","text":"Kodo vykdymas be jokios savo serverių priežiūros: tiekėjas jį paleidžia prireikus, o tu moki už tai, ką sunaudoji."},{"id":"lb","g":"change","word":"Apkrovos skirstytuvas","text":"Priemonė, paskirstanti lankytojus tarp kelių serverių, kad nė vienas nebūtų perkrautas.","also":["load balancers","apkrovos skirstytuvai"]},{"id":"cache","g":"change","word":"Podėlis","text":"Netoliese laikoma patogi naujausių rezultatų saugykla, kad nereikėtų to paties vėl parsiųsti ar apskaičiuoti. Ją išvalius kartais susitvarko pasenę puslapiai.","also":["caches","caching","cached","podėliai","spartinančioji atmintinė"]},{"id":"cdn","g":"change","word":"Turinio pateikimo tinklas (CDN)","text":"Visame pasaulyje išdėstyti serveriai, laikantys tavo puslapių ir paveikslėlių kopijas arti lankytojų, kad jos būtų greitai įkeliamos.","also":["CDN"]},{"id":"migration","g":"change","word":"Migravimas","text":"Duomenų ar sistemų perkėlimas iš senos aplinkos į naują arba kruopštus duomenų bazės sandaros pakeitimas.","also":["migrations","database migration","duomenų bazės migravimas"]},{"id":"service","g":"run","word":"Paslauga","text":"Kažkas, ką sukūrei ir kuo žmonės pasikliauja, pavyzdžiui, svetainė ar programėlė, prižiūrima, kad ir toliau veiktų. Pažymėk „Šis projektas yra paslauga“ ir nurodyk, ką ji siūlo, kas ja naudojasi ir kas budi.","also":["paslaugos","service"]},{"id":"uptimepct","g":"run","word":"Veikimo laikas","text":"Kokią laiko dalį paslauga veikia, paprastai procentais. Net 99,9 % leidžia apie 43 minutes prastovos per mėnesį.","also":["uptime percentage","veikimo procentas"]},{"id":"uptime","g":"run","word":"Veikimo patikra","text":"Automatinė patikra kas kelias minutes, ar tavo paslauga vis dar atsako. Jei ji kelis kartus iš eilės nepavyksta, AI-gile pati atidaro incidento kortelę.","also":["uptime checks","veikimo patikrinimai"]},{"id":"statuspage","g":"run","word":"Būsenos puslapis","text":"Viešas puslapis, rodantis, ar paslauga veikia (žalia, oranžinė ar raudona), su naujausia žinute, kad naudotojai galėtų pasitikrinti patys, užuot klausę.","also":["būsenos puslapiai","status page"]},{"id":"desk","g":"run","word":"Aptarnavimo stalas","text":"Vieta, į kurią ateina klausimai ir pranešimai iš žmonių, naudojančių tavo paslaugą. AI-gile kiekvieną priskiria prašymui, incidentui ar idėjai ir pasako, jei tai panašu į kažką, apie ką jau pranešta.","also":["aptarnavimo stalai","pagalbos tarnyba","service desk"]},{"id":"svcrequest","g":"run","word":"Paslaugos prašymas","text":"Kai kas nors prašo įprasto dalyko, pavyzdžiui, naujos paskyros ar truputį pagalbos, o ne praneša, kad kažkas sugedo. Jis laukia savo eilės; incidentas eina pirmas.","also":["paslaugos prašymai","paslaugos prašymą","prašymas"]},{"id":"incident","g":"run","word":"Incidentas","text":"Tai, kas dabar sugedę ar netinkamai veikia naudotojams, pavyzdžiui, nepasiekiama ar labai lėta svetainė. 🔥 Incidento kortelė aplenkia eilę: pirmiausia atkuriamas veikimas.","also":["incidentai"]},{"id":"major","g":"run","word":"Didelis incidentas","text":"Didelis incidentas: paveikta daug žmonių arba gresia pavojus pinigams ar duomenims. Vienas mygtukas visas komandas nukreipia į jį (spiečius), pažadina budintįjį ir kas 30 minučių prašo būsenos naujienos.","also":["dideli incidentai","major incident"]},{"id":"oncall","g":"run","word":"Budėjimas","text":"Būti tuo, kuris atsiliepia, kai kas nors sugenda, net naktį. Kiekviena paslauga turi budintį komandos narį, kuris pirmas pažadinamas dėl jos incidentų.","also":["budintis","on call","on-call"]},{"id":"replyby","g":"run","word":"Atsakymo terminas","text":"Kiek ilgai kortelė gali laukti pirmojo atsakymo, pavyzdžiui, valandą incidentui. Po to ji gauna raudoną laikrodį, kad niekas nebūtų tyliai pamirštas. Dar vadinama atsakymo tikslu.","also":["atsakymo terminai","atsakymo tikslas","response target"]},{"id":"postmortem","g":"run","word":"Incidento analizė","text":"Trumpas žvilgsnis atgal po incidento: kas nutiko, kas padėjo ir ką pakeisti, nieko nekaltinant. Be jos incidento uždaryti negalima. Angliškai tai vadinama post-mortem.","also":["post-mortem","postmortem","poincidentinė analizė"]},{"id":"problem","g":"run","word":"Problema","text":"Paslėpta vieno ar kelių incidentų priežastis. 🧩 Problemos kortelė sugrupuoja vis pasikartojančius incidentus, kad priežastis būtų rasta ir sutaisyta visam laikui.","also":["problemos"],"noTip":1},{"id":"rootcause","g":"run","word":"Pagrindinė priežastis","text":"Tikroji priežastis, kodėl kažkas sugedo, o ne tik tai, ką matei negerai veikiant. Sutaisyk pagrindinę priežastį, ir incidentas nebesikartos.","also":["pagrindinės priežastys","šakninė priežastis","root cause"]},{"id":"workaround","g":"run","word":"Laikinas sprendimas","text":"Būdas išlaikyti viską veikiantį, kol tikras pataisymas bus paruoštas, pavyzdžiui, ką nors paleisti iš naujo, kai užstringa. Jis užrašomas ant problemos kortelės, kad niekam nereikėtų to vėl išsiaiškinti.","also":["laikini sprendimai","workaround"]},{"id":"knownerror","g":"run","word":"Žinoma klaida","text":"Problema, kurios priežastis žinoma, bet dar nepašalinta, paprastai su užrašytu laikinu sprendimu. 🧩 Žinomų klaidų sąraše visi gali jį rasti, užuot tyrę iš naujo.","also":["žinomos klaidos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Žingsnis po žingsnio instrukcija, kaip sutaisyti žinomos rūšies bėdą, kad kiekvieną kartą būtų daroma taip pat ir greitai. Po didelio incidento komanda gali pasiūlyti tokią, o tu duosi savo OK.","also":["runbook","veiksmų instrukcija"]},{"id":"ci","g":"run","word":"Konfigūracijos elementas","text":"Vienas dalykas, nuo kurio priklauso tavo paslauga, pavyzdžiui, serveris, domenas, sertifikatas, raktas ar tiekėjas. 🗂️ Konfigūracijos elementai pateikia juos pagal paslaugas, todėl matai, ką paveikia incidentas ir ką reikia atnaujinti ar sukurti atsarginę kopiją.","also":["konfigūracijos elementai","konfigūracijos elementą","konfigūracijos elementų"]},{"id":"expiry","g":"run","word":"Galiojimo pabaigos data","text":"Data, kai kas nors nustos veikti, jei nebus pratęsta, pavyzdžiui, svetainės saugumo sertifikatas ar domenas. AI-gile stebi šias datas ir kiekvienam atnaujinimui prieš 30 dienų sukuria po kortelę, kad niekas nenustotų veikti netikėtai.","also":["galiojimo pabaigos datos","galiojimo pabaiga","galiojimo stebėjimas"]},{"id":"backup","g":"run","word":"Atsarginė kopija","text":"Išsaugota ankstesnė tavo duomenų kopija, kuria galima pasinaudoti, jei kas nors dingsta ar sugadinama. AI-gile kasdien daro tavo lentų atsarginę kopiją.","also":["atsarginės kopijos","backup"]},{"id":"restore","g":"run","word":"Atkūrimas","text":"Duomenų sugrąžinimas iš atsarginės kopijos. Atsarginė kopija iš tikrųjų vertinga tik tada, kai žinai, kad ją galima atkurti, todėl verta kartais pabandyti.","also":["atkurti","atkurta","restore"]},{"id":"svcreview","g":"run","word":"Paslaugos peržiūra","text":"Žvilgsnis atgal į vieną paslaugos mėnesį: atidaryti ir sutaisyti incidentai, kaip greitai žmonės gavo atsakymą, veikimo laikas ir sunaudoti žetonai. Mėnesio peržiūra tai rodo kiekvienai paslaugai.","also":["paslaugų peržiūros","mėnesio peržiūra","mėnesio peržiūros"]},{"id":"accessreview","g":"run","word":"Prieigos peržiūra","text":"Kas 90 dienų tikrinama, kas vis dar turi prieigą: bendrinimo nuorodos, draugų vaidmenys, išsaugoti slaptažodžiai ir raktai. Kiekvieną palieki arba pašalini, kad sena prieiga neužsiliktų.","also":["prieigos peržiūros","prieigos peržiūrą"]},{"id":"improvements","g":"run","word":"Patobulinimų sąrašas","text":"Viskas, ką komanda nusprendė daryti geriau, vienoje vietoje: retro pasiūlymai, peržiūrų veiksmai ir problemų sprendimai, kiekvienas su savo būsena. Rasi tai skiltyje 📈 Patobulinimai.","also":["patobulinimų sąrašai","patobulinimai"]},{"id":"tokencap","g":"run","word":"Žetonų limitas","text":"Mėnesinis limitas žetonams, kuriuos gali naudoti paslaugos agentai. Pasiekus 80 % gauni įspėjimą; pasiekus 100 % jų foninis darbas laukia kito mėnesio arba kol padidinsi limitą.","also":["žetonų limitai","mėnesinis žetonų limitas"]},{"id":"svcmgmt","g":"run","word":"Paslaugų valdymas","text":"Viskas, ko reikia, kad paslauga kasdien išliktų naudinga ir veiktų tiems, kurie ja pasikliauja.","also":["paslaugos valdymas"]},{"id":"itil","g":"run","word":"ITIL","text":"Plačiai naudojamas gero paslaugų valdymo vadovas, apimantis incidentus, problemas ir pakeitimus. Pavadinimas kadaise reiškė IT infrastruktūros biblioteką."},{"id":"itsm","g":"run","word":"IT paslaugų valdymas (ITSM)","text":"Technologijų teikimas žmonėms kaip paslaugos, aiškiai tvarkant prašymus, incidentus, pakeitimus ir tobulinimą.","also":["ITSM"]},{"id":"managed","g":"run","word":"Valdoma paslauga","text":"Paslauga, kurią tau teikia ir prižiūri kas nors kitas pagal susitarimą, kaip gerai ji turi veikti.","also":["managed services","valdomos paslaugos"]},{"id":"svcowner","g":"run","word":"Paslaugos savininkas","text":"Žmogus, atsakingas už visą paslaugą: jos veikimą, kainą ir tobulėjimą.","also":["service owners","paslaugų savininkai"]},{"id":"sla","g":"run","word":"Paslaugos lygio susitarimas (SLA)","text":"Rašytinis pažadas klientams, kaip gerai paslauga veiks, pavyzdžiui, „veiks 99,9 % laiko“ ar „atsakysime per valandą“. Už pažeidimą dažnai numatytas pinigų grąžinimas.","also":["SLA","SLAs","service level agreement","paslaugos lygio susitarimas"]},{"id":"slo","g":"run","word":"Paslaugos lygio tikslas (SLO)","text":"Pačios komandos tikslas, kaip gerai paslauga turėtų veikti per laikotarpį. Dėl atsargos jis paprastai šiek tiek griežtesnis už SLA.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Paslaugos lygio rodiklis (SLI)","text":"Tikrasis matavimas, lyginamas su tikslu, pavyzdžiui, sėkmingai įkeltų puslapių dalis.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Pasiekiamumas","text":"Ar žmonės gali naudotis paslauga tada, kai reikia. Dažnai matuojama veikimo laiku.","also":["high availability","didelis pasiekiamumas"]},{"id":"downtime","g":"run","word":"Prastova","text":"Laikas, kai paslauga neveikia ar yra išjungta, planuotai arba ne.","also":["down time","neveikimo laikas"]},{"id":"errorbudget","g":"run","word":"Klaidų biudžetas","text":"Nedidelė nesėkmių dalis, kurią leidžia tavo patikimumo tikslas. Kol jos likę, galima rizikuoti pakeitimais; išnaudojus tempas lėtinamas.","also":["error budgets","klaidų biudžetai"]},{"id":"outage","g":"run","word":"Sutrikimas","text":"Laikotarpis, kai paslauga naudotojams neveikia arba veikia labai blogai.","also":["outages","sutrikimai"]},{"id":"degraded","g":"run","word":"Suprastėjęs veikimas","text":"Veikia, bet prastai: lėtai arba neveikiant daliai funkcijų.","also":["degraded service","suprastėjusi paslauga"]},{"id":"monitoring","g":"run","word":"Stebėsena","text":"Nuolatinis automatinis paslaugos stebėjimas, kad problemos būtų pastebėtos, geriausia dar prieš naudotojus."},{"id":"observability","g":"run","word":"Stebimumas","text":"Kaip gerai iš išorės galima suprasti, kas vyksta sistemos viduje, naudojant jos žurnalus, rodiklius ir užklausų pėdsakus.","also":["o11y"]},{"id":"log","g":"run","word":"Žurnalas","text":"Nuolat pildomas programos veiksmų dienoraštis, padedantis suprasti, kas sugedo.","also":["logs","logging","žurnalai","registravimas"],"noTip":1},{"id":"trace","g":"run","word":"Užklausos pėdsakas","text":"Įrašas, kaip viena užklausa žingsnis po žingsnio keliauja per sistemos dalis, rodantis, kur ji sulėtėjo.","also":["traces","tracing","pėdsakai"]},{"id":"latency","g":"run","word":"Delsa","text":"Kiek trunka sulaukti atsakymo, pavyzdžiui, nuo paspaudimo iki pasirodant puslapiui."},{"id":"alert","g":"run","word":"Įspėjimas","text":"Automatinis pranešimas, kad į ką nors reikia atkreipti dėmesį, pavyzdžiui, svetainė neatsako.","also":["alerts","alerting","įspėjimai"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Nuovargis nuo įspėjimų","text":"Kai įspėjimų tiek daug, kad žmonės pradeda juos ignoruoti, įskaitant svarbius.","also":["alarm fatigue","įspėjimų nuovargis"]},{"id":"dashboard","g":"run","word":"Suvestinė","text":"Ekranas, kuriame vienu žvilgsniu matyti svarbiausi skaičiai ir būsenos.","also":["dashboards","suvestinės"],"noTip":1},{"id":"paging","g":"run","word":"Skubus budinčiojo iškvietimas","text":"Skubus skambutis ar budinčio žmogaus pažadinimas dėl problemos.","also":["paged"]},{"id":"escalation","g":"run","word":"Perdavimas aukštesniam lygiui","text":"Daugiau įgūdžių ar įgaliojimų turinčio žmogaus įtraukimas, kai problemos dabartiniu lygiu nepavyksta išspręsti arba tai vyksta per lėtai.","also":["escalate","escalated","eskalavimas"]},{"id":"triage","g":"run","word":"Pirminis rūšiavimas","text":"Greitas gaunamų problemų rikiavimas pagal skubumą ir svarbą, kad pirmiausia būtų sprendžiamos rimčiausios.","also":["triaged"]},{"id":"impact","g":"run","word":"Poveikis","text":"Kiek kas nors paveikia žmones: kiek jų ir kaip stipriai.","noTip":1},{"id":"urgency","g":"run","word":"Skubumas","text":"Kaip greitai reikia ką nors išspręsti. Poveikis ir skubumas kartu lemia prioritetą.","noTip":1},{"id":"plevels","g":"run","word":"Prioriteto lygiai (P1, P2…)","text":"Žymos, nurodančios problemos skubumą. P1 yra rimčiausias ir reikalauja veikti iš karto.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Prašymų eilė","text":"Prašymų ir incidentų, laukiančių, kol kas nors jų imsis, sąrašas.","also":["ticket queues","prašymų eilės"]},{"id":"tiers","g":"run","word":"Pirmasis ir antrasis pagalbos lygiai","text":"Pagalbos lygiai: pirmasis priima kreipimąsi ir sprendžia paprastas problemas, antrasis turi gilesnių žinių sudėtingesnėms. Dar vadinami 1 ir 2 pakopomis.","also":["first-line support","tier 1","tier 2","pirmasis lygis","antrasis lygis"]},{"id":"ic","g":"run","word":"Incidento vadovas","text":"Vienas žmogus, vadovaujantis incidento sprendimui, kad visi žinotų, kas priima sprendimus ir kas ką daro.","also":["incident commanders","incidentų vadovai"]},{"id":"responsetime","g":"run","word":"Reagavimo laikas","text":"Laikas, per kurį kas nors pirmą kartą imasi prašymo ar incidento.","also":["response times","reagavimo laikai"]},{"id":"resolution","g":"run","word":"Išsprendimo laikas","text":"Laikas, per kurį prašymas ar incidentas visiškai išsprendžiamas, nuo pranešimo iki pataisymo.","also":["resolution times","time to resolve","išsprendimo trukmė"]},{"id":"mttr","g":"run","word":"Vidutinis atkūrimo laikas (MTTR)","text":"Kiek vidutiniškai trunka atkurti paslaugą jai sugedus. MTTR gali turėti kiek skirtingų reikšmių, todėl nurodyk, ką matuoji.","also":["MTTR","mean time to restore","vidutinis atkūrimo laikas"]},{"id":"mtbf","g":"run","word":"Vidutinis laikas tarp gedimų (MTBF)","text":"Kiek vidutiniškai laiko paslauga veikia iki kito gedimo.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfigūracijos valdymo duomenų bazė (CMDB)","text":"Visų konfigūracijos elementų ir jų ryšių sąrašas, rodantis, kas nuo ko priklauso.","also":["CMDB"]},{"id":"asset","g":"run","word":"Turtas","text":"Viskas, kas turi vertę ir ką turi ar už ką moki paslaugai teikti, pavyzdžiui, nešiojamasis kompiuteris, programos licencija ar domenas.","also":["assets","turto vienetai"],"noTip":1},{"id":"capplan","g":"run","word":"Pajėgumų planavimas","text":"Rūpinimasis, kad būsimiems poreikiams pakaktų kompiuterių galios, vietos duomenims ir žmonių.","also":["capacity plan","pajėgumų planas"]},{"id":"scaling","g":"run","word":"Pajėgumų didinimas","text":"Prisitaikymas prie didesnio naudotojų skaičiaus didinant vieno įrenginio galią (vertikalus plėtimas) arba pridedant daugiau įrenginių (horizontalus plėtimas).","also":["scale up","scale out","scaling up","scaling out","vertikalus plėtimas","horizontalus plėtimas"]},{"id":"bcp","g":"run","word":"Veiklos tęstinumas","text":"Planai, kaip tęsti svarbiausią veiklą nutikus didelei nelaimei, pavyzdžiui, netekus biuro, svarbaus tiekėjo ar kompiuterių.","also":["business continuity plan","veiklos tęstinumo planas"]},{"id":"dr","g":"run","word":"Atkūrimas po nelaimės (DR)","text":"Planas ir įrankiai paslaugai atkurti po rimto įvykio, pavyzdžiui, praradus visą duomenų centrą.","also":["disaster recovery","atkūrimas po nelaimės"]},{"id":"rto","g":"run","word":"Atkūrimo laiko tikslas (RTO)","text":"Ilgiausias leistinas paslaugos neveikimo laikas po nelaimės, iki ji turi vėl veikti.","also":["RTO"]},{"id":"rpo","g":"run","word":"Atkūrimo taško tikslas (RPO)","text":"Kiek naujausių duomenų galėtum prarasti, išreiškiant laiku. Vienos valandos RPO reiškia atsargines kopijas bent kas valandą.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Rezervavimas","text":"Paruoštų atsargų, pavyzdžiui, antro serverio, turėjimas, kad vienas gedimas nesustabdytų paslaugos."},{"id":"failover","g":"run","word":"Automatinis perjungimas į rezervą","text":"Automatinis persijungimas į atsarginę sistemą sugedus pagrindinei.","also":["fail over","perjungimas į rezervą"]},{"id":"spof","g":"run","word":"Vienintelis gedimo taškas","text":"Viena dalis, kuriai sugedus sustoja viskas, nes nėra atsarginės.","also":["single points of failure","SPOF","vieninteliai gedimo taškai"]},{"id":"maintwin","g":"run","word":"Priežiūros laikotarpis","text":"Suplanuotas laikas, kai dėl priežiūros paslauga gali būti sustabdyta ar lėtesnė. Naudotojai įspėjami iš anksto.","also":["maintenance windows","planned maintenance","planuota priežiūra"]},{"id":"handover","g":"run","word":"Perdavimas","text":"Darbo, žinių ir atsakomybės perdavimas kitam žmogui ar komandai, kad niekas nepasimestų.","also":["handovers","perdavimai"]},{"id":"kb","g":"run","word":"Žinių bazė","text":"Pagalbos straipsnių ir atsakymų rinkinys naudotojams ir komandai.","also":["knowledge bases","žinių bazės"]},{"id":"csat","g":"run","word":"Klientų pasitenkinimas (CSAT)","text":"Naudotojų įvertinimas, kiek jie patenkinti. Dažnai jo prašoma uždarius prašymą.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Tiekėjas","text":"Išorinė įmonė, kuria pasikliauji, pavyzdžiui, prieglobos tiekėjas. Dar vadinama trečiąja šalimi.","also":["suppliers","vendor","vendors","third party","tiekėjai","trečioji šalis"],"noTip":1},{"id":"retire","g":"run","word":"Paslaugos uždarymas","text":"Saugus galutinis paslaugos išjungimas: pranešama naudotojams, sutvarkomi duomenys bei prieiga ir nutraukiamos išlaidos.","also":["retiring a service","paslaugos atsisakymas"]},{"id":"eol","g":"run","word":"Palaikymo pabaiga (EOL)","text":"Kai gamintojas nebeatnaujina ar nebepalaiko produkto, todėl jį reikėtų pakeisti.","also":["EOL","end-of-life","gyvavimo pabaiga"]},{"id":"cybersec","g":"sec","word":"Kibernetinis saugumas","text":"Sistemų ir duomenų saugojimas nuo įsilaužimo, vagystės ar sugadinimo.","also":["cyber security","kibernetinis saugumas"]},{"id":"authn","g":"sec","word":"Tapatumo nustatymas","text":"Tikrinimas, kas yra žmogus, dažniausiai slaptažodžiu ar kodu. Dažnai trumpinama authn.","also":["authn","autentifikavimas"]},{"id":"authz","g":"sec","word":"Prieigos teisių tikrinimas","text":"Tikrinimas, ką žmogui leidžiama daryti, jau žinant jo tapatybę. Dažnai trumpinama authz.","also":["authz","authorization","autorizavimas"]},{"id":"mfa","g":"sec","word":"Daugiaveiksnis tapatumo nustatymas (MFA)","text":"Prisijungimas pateikiant du ar daugiau įrodymų, pavyzdžiui, slaptažodį ir kodą telefone. Dviejų įrodymų atveju dar vadinama 2FA.","also":["MFA","2FA","two-factor","two-factor authentication","dviejų veiksnių autentifikavimas"]},{"id":"sso","g":"sec","word":"Bendrasis prisijungimas (SSO)","text":"Vienas prisijungimas prie daugelio sistemų, pavyzdžiui, visur naudojant darbo paskyrą.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Slaptažodžių tvarkyklė","text":"Programėlė, sukurianti stiprius slaptažodžius ir juos prisimenanti už tave.","also":["password managers","slaptažodžių tvarkyklės"]},{"id":"secret","g":"sec","word":"Slaptas duomuo","text":"Slaptažodis, raktas ar kitas privatus kodas, kuriuo programa kur nors prisijungia. Jo niekada negalima viešinti ar rašyti į kodą.","also":["secrets","slapti duomenys"],"noTip":1},{"id":"apikey","g":"sec","word":"API raktas","text":"Slaptas kodas, leidžiantis programai naudoti kitos paslaugos API ir rodantis, kas ja naudojasi bei už ją moka.","also":["API keys","API raktai"]},{"id":"accesstoken","g":"sec","word":"Prieigos raktas","text":"Laikinas leidimas, įrodantis programos teisę prisijungti, kad nereikėtų kiekvieną kartą tavo slaptažodžio. Tai ne tas pats, kas AI žetonas.","also":["access tokens","prieigos raktai"]},{"id":"encryption","g":"sec","word":"Šifravimas","text":"Informacijos užkodavimas taip, kad ją perskaitytų tik turintis tinkamą raktą.","also":["encrypted","encrypt","šifruota","užšifruoti"]},{"id":"https","g":"sec","word":"HTTPS","text":"Saugus tinklalapių perdavimo būdas, naršyklėje žymimas spynele, kad tarpininkai negalėtų jų perskaityti ar pakeisti."},{"id":"cert","g":"sec","word":"SSL/TLS sertifikatas","text":"Skaitmeninis tapatybės dokumentas, leidžiantis svetainei įrodyti savo tapatybę ir naudoti HTTPS. Jis baigia galioti, todėl jį reikia atnaujinti.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikatas","sertifikatai"]},{"id":"permissions","g":"sec","word":"Leidimai","text":"Taisyklės, nurodančios, kas ką gali matyti ar keisti.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mažiausios teisės","text":"Kiekvienam žmogui ar programai suteikiama tik iš tikrųjų reikalinga prieiga ir tik tiek laiko, kiek jos reikia.","also":["principle of least privilege","mažiausių teisių principas"]},{"id":"rbac","g":"sec","word":"Vaidmenimis grįstas prieigos valdymas (RBAC)","text":"Prieigos suteikimas pagal vaidmenį, pavyzdžiui, stebėtojas ar redaktorius, o ne kiekvienam žmogui atskirai.","also":["RBAC","role-based access","vaidmenimis grįsta prieiga"]},{"id":"vuln","g":"sec","word":"Pažeidžiamumas","text":"Silpna vieta, kuria kas nors galėtų pasinaudoti įsilaužti ar pakenkti.","also":["vulnerabilities","pažeidžiamumai"]},{"id":"zeroday","g":"sec","word":"Nulinės dienos spraga","text":"Silpna vieta, apie kurią užpuolikai žino dar prieš kūrėjams turint laiko ją pataisyti.","also":["zero-days","zero day","nulinės dienos spragos"]},{"id":"malware","g":"sec","word":"Kenkėjiška programinė įranga","text":"Žalingos programos, pavyzdžiui, virusai, skirtos gadinti, šnipinėti ar vogti."},{"id":"ransomware","g":"sec","word":"Išpirkos reikalaujanti programa","text":"Kenkėjiška programa, užrakinanti failus ir reikalaujanti pinigų už jų atrakinimą. Geros atsarginės kopijos – geriausia apsauga.","also":["ransomware attack","išpirkos ataka"]},{"id":"phishing","g":"sec","word":"Duomenų viliojimas","text":"Suklastotos žinutės, bandančios išvilioti slaptažodžius ar pinigus arba priversti atidaryti ką nors žalinga.","also":["phishing email","phishing emails","apgaulingi laiškai"]},{"id":"socialeng","g":"sec","word":"Socialinė inžinerija","text":"Žmonių, o ne kompiuterių apgaudinėjimas siekiant gauti prieigą, pavyzdžiui, apsimetant IT pagalba telefonu."},{"id":"firewall","g":"sec","word":"Užkarda","text":"Sargas, sprendžiantis, kokį tinklo srautą įleisti ar išleisti.","also":["firewalls","užkardos"]},{"id":"vpn","g":"sec","word":"VPN","text":"Virtualiojo privačiojo tinklo santrumpa: privatus šifruotas ryšys internetu, dažnai naudojamas saugiai pasiekti darbo sistemas.","also":["virtual private network","virtualus privatusis tinklas"]},{"id":"ddos","g":"sec","word":"Paslaugos trikdymas (DoS, DDoS)","text":"Paslaugos užtvindymas netikru srautu, kad tikri žmonės negalėtų ja naudotis. DDoS reiškia, kad srautas vienu metu ateina iš daugybės kompiuterių.","also":["DoS","DDoS","denial of service","DDoS attack","DDoS ataka"]},{"id":"pentest","g":"sec","word":"Įsilaužimo testas","text":"Samdomi patikimi specialistai pabando įsilaužti, kad silpnos vietos būtų aptiktos anksčiau nei jas ras tikri užpuolikai.","also":["pen test","pen testing","penetration testing","pentest","įsilaužimo testavimas"]},{"id":"audit","g":"sec","word":"Saugumo auditas","text":"Kruopštus apsaugos patikrinimas pagal gerosios praktikos sąrašą.","also":["security audits","saugumo auditai"]},{"id":"threatmodel","g":"sec","word":"Grėsmių modeliavimas","text":"Apmąstymas, kas ir kaip galėtų pulti sistemą bei ką darytum, kad juos sustabdytum.","also":["threat model","threat modeling","grėsmių modelis"]},{"id":"breach","g":"sec","word":"Duomenų saugumo pažeidimas","text":"Kai privati informacija pasiekia tuos, kurie neturėtų jos turėti, arba be leidimo prarandama ar pakeičiama.","also":["data breaches","duomenų saugumo pažeidimai"]},{"id":"pii","g":"sec","word":"Asmens duomenys","text":"Bet kokia informacija apie žmogų, kurio tapatybę galima nustatyti, pavyzdžiui, vardas, el. paštas ar buvimo vieta. Dar vadinama PII.","also":["PII","personally identifiable information","asmens tapatybę atskleidžianti informacija"]},{"id":"gdpr","g":"sec","word":"BDAR (GDPR)","text":"Europos asmens duomenų teisės aktas (Jungtinė Karalystė turi savo versiją): rink tik tai, ko reikia, saugok duomenis ir leisk žmonėms peržiūrėti ar ištrinti savuosius.","also":["General Data Protection Regulation","Bendrasis duomenų apsaugos reglamentas"]},{"id":"dataprot","g":"sec","word":"Duomenų apsauga","text":"Tinkamas ir teisėtas rūpinimasis asmens duomenimis.","also":["data protection law","duomenų apsaugos teisė"]},{"id":"privacypolicy","g":"sec","word":"Privatumo politika","text":"Viešas puslapis, nurodantis, kokius asmens duomenis renki, kodėl ir ką su jais darai.","also":["privacy statement","privacy notice","privatumo pranešimas"]},{"id":"consent","g":"sec","word":"Sutikimas","text":"Aiškus, laisvai duotas žmogaus sutikimas naudoti jo duomenis konkrečiu būdu. Jis gali bet kada jį atšaukti.","also":["opt-in","aiškus sutikimas"],"noTip":1},{"id":"cookie","g":"sec","word":"Slapukas","text":"Nedidelis failas, kurį svetainė išsaugo naršyklėje, kad prisimintų, pavyzdžiui, tavo prisijungimą. Kai kuriems pirmiausia reikia tavo sutikimo.","also":["cookies","slapukai"],"noTip":1},{"id":"minimisation","g":"sec","word":"Duomenų kiekio mažinimas","text":"Tik tų asmens duomenų, kurių iš tikrųjų reikia darbui, rinkimas ir saugojimas.","also":["data minimization","duomenų kiekio mažinimas"]},{"id":"retention","g":"sec","word":"Duomenų saugojimo trukmė","text":"Kiek laiko duomenys laikomi iki ištrinant. Saugiau jų nelaikyti ilgiau nei reikia, ir to dažnai reikalauja teisė.","also":["retention period","saugojimo laikotarpis"]},{"id":"anon","g":"sec","word":"Anoniminimas","text":"Duomenų pakeitimas taip, kad iš jų pagrįstai nebebūtų galima nustatyti jokio žmogaus tapatybės.","also":["anonymised","anonymization","anonymous data","anoniminiai duomenys"]},{"id":"pseudo","g":"sec","word":"Pseudoniminimas","text":"Vardų ir kitų detalių pakeitimas kodais, atskirai laikant raktą sąsajoms atkurti. Tai vis dar asmens duomenys.","also":["pseudonymised","pseudonymization","pseudoniminti duomenys"]},{"id":"dpa","g":"sec","word":"Duomenų tvarkymo sutartis (DPA)","text":"Sutartis, nurodanti, kaip tiekėjas gali tvarkyti asmens duomenis tavo vardu.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Poveikio duomenų apsaugai vertinimas (DPIA)","text":"Kruopštus išankstinis vertinimas, kaip sumanytas asmens duomenų naudojimas gali paveikti žmones ir kaip sumažinti riziką.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audito žurnalas","text":"Įrašas, kas ką ir kada atliko, kad vėliau būtų galima patikrinti veiksmus.","also":["audit logs","audit trail","audito pėdsakas"]},{"id":"compliance","g":"sec","word":"Atitiktis","text":"Taikomų įstatymų, taisyklių ir standartų laikymasis bei gebėjimas tai parodyti.","also":["compliant","atitinkantis reikalavimus"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Gerai žinomas tarptautinis informacijos saugumo valdymo standartas. Įmonės gali gauti jo sertifikatą.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"JAV ataskaita, patikrinta išorinių auditorių ir rodanti, kad įmonė tinkamai rūpinasi klientų duomenimis.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI, kuris savarankiškai atlieka užduotį: skaito kodą, daro pakeitimus, atlieka patikrinimus ir pateikia rezultatą. Jo darbas vis tiek tikrinamas.","also":["agents","agentas","agentai"]},{"id":"token","g":"ai","word":"Token","text":"Maži teksto gabalėliai, kuriuos AI skaito ir rašo, vidutiniškai maždaug trys ketvirtadaliai žodžio. AI naudojimas skaičiuojamas žetonais, todėl naudojant mažiau jų lieka daugiau tavo plano išteklių.","also":["tokens","žetonas","žetonai"]},{"id":"hook","g":"ai","word":"Hook","text":"Trumpa komanda, automatiškai vykdoma nustatytu momentu, pavyzdžiui, prasidėjus AI sesijai, kad komanda gautų tavo komentarus.","also":["hooks","kabliukas","kabliukai"]},{"id":"ai","g":"ai","word":"Dirbtinis intelektas (AI)","text":"Kompiuterinės sistemos, atliekančios darbus, kuriems, mūsų manymu, paprastai reikia žmogaus, pavyzdžiui, rašančios, atsakančios į klausimus ar atpažįstančios vaizdus.","also":["AI","DI","artificial intelligence","dirbtinis intelektas"],"noTip":1},{"id":"ml","g":"ai","word":"Mašininis mokymasis (ML)","text":"Būdas išmokyti kompiuterius atpažinti dėsningumus iš daugybės pavyzdžių, užuot davus tikslias taisykles.","also":["machine learning","mašininis mokymasis"]},{"id":"model","g":"ai","word":"Modelis","text":"Išmokytos AI sistemos „smegenys“, sukurtos mokantis iš daugybės pavyzdžių. Modeliai skiriasi gebėjimais, sparta ir kaina.","also":["models","AI model","modeliai","AI modelis","DI modelis"],"noTip":1},{"id":"llm","g":"ai","word":"Didysis kalbos modelis (LLM)","text":"AI modelis, išmokytas iš didžiulio kiekio tekstų, kad galėtų skaityti ir rašyti.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generatyvinis AI","text":"AI, kuriantis naujus dalykus, pavyzdžiui, tekstą, vaizdus ar kodą, o ne tik juos rūšiuojantis ar atpažįstantis.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Pokalbių robotas","text":"Programa, su kuria bendrauji įprasta kalba, raštu ar balsu.","also":["chatbots","pokalbių robotai"]},{"id":"prompt","g":"ai","word":"Užklausa (prompt)","text":"Tai, ką pateiki AI: klausimas ar nurodymai ir visa papildoma medžiaga. Aiškesnės užklausos paprastai duoda geresnius atsakymus.","also":["prompts","promptas","promptai"]},{"id":"prompteng","g":"ai","word":"Užklausų kūrimas","text":"Gebėjimas rašyti užklausas, kurios duoda patikimus ir naudingus rezultatus.","also":["užklausų formulavimas"]},{"id":"sysprompt","g":"ai","word":"Sistemos nurodymai","text":"Foniniai nurodymai, kuriuos AI gauna prieš pokalbį ir kurie nustato jo vaidmenį bei taisykles. Jie svarbesni už tavo įvedamą tekstą.","also":["system prompts","system instruction","system instructions","sistemos užklausa"]},{"id":"context","g":"ai","word":"Kontekstas","text":"Viskas, ką AI mato dirbdamas: nurodymai, tavo žinutės, perskaityti failai ir ankstesni atsakymai.","noTip":1},{"id":"ctxwin","g":"ai","word":"Konteksto langas","text":"Kiek AI vienu metu gali išlaikyti mintyje, matuojant žetonais. Viršijus ribą senesnės dalys pašalinamos ar apibendrinamos.","also":["context windows","konteksto langai"]},{"id":"session","g":"ai","word":"Sesija","text":"Vienas darbo pokalbis su AI nuo pradžios iki pabaigos. Nauja sesija prasideda su nauja atmintimi.","also":["sessions","sesijos"],"noTip":1},{"id":"memory","g":"ai","word":"Atmintis","text":"Užrašai, kuriuos AI išsaugo tarp sesijų, kad prisimintų tavo nuostatas ir ankstesnius sprendimus.","noTip":1},{"id":"hallucination","g":"ai","word":"Haliucinacija","text":"Kai AI užtikrintai pasako ką nors išgalvota ar klaidinga. Svarbius faktus tikrink.","also":["hallucinations","hallucinate","hallucinates","haliucinacijos"]},{"id":"training","g":"ai","word":"Mokymas","text":"Modelio mokymas pateikiant daugybę pavyzdžių dar prieš pradedant juo naudotis.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Mokymo duomenys","text":"Pavyzdžiai, iš kurių mokėsi modelis. Jo žinios siekia tik laiką, kai tie duomenys buvo surinkti.","also":["training set","mokymo rinkinys"]},{"id":"cutoff","g":"ai","word":"Žinių riba","text":"Data, ties kuria baigiasi AI turimos žinios. Apie vėlesnius įvykius jis nežinos, nebent pasidomės papildomai.","also":["training cutoff","mokymo duomenų riba"]},{"id":"finetune","g":"ai","word":"Papildomas mokymas","text":"Papildomas esamo modelio mokymas tavo pavyzdžiais, kad jis geriau atliktų konkretų darbą.","also":["fine-tune","fine-tuned","fine tuning","tikslinis mokymas"]},{"id":"inference","g":"ai","word":"Modelio vykdymas","text":"Tikrasis AI modelio naudojimas atsakymui gauti, o ne jo mokymas.","also":["model inference","išvedimas"]},{"id":"tooluse","g":"ai","word":"Įrankių naudojimas","text":"AI galimybė ne tik kalbėti, bet ir veikti: vykdyti komandas, skaityti failus ar ieškoti internete programėlės suteiktais įrankiais.","also":["tool calling","tool call","tool calls","įrankio iškvietimas"]},{"id":"subagent","g":"ai","word":"Pagalbinis agentas","text":"Pagalbinis AI, kuriam pagrindinis AI perduoda mažesnį darbą ir iš kurio gauna rezultatą.","also":["subagents","sub-agent","pagalbiniai agentai"]},{"id":"multiagent","g":"ai","word":"Kelių agentų veikimas","text":"Keli AI kartu atlieka vieną darbą, kiekvienas savo dalį, tarsi nedidelė komanda.","also":["multi-agent system","kelių agentų sistema"]},{"id":"autonomy","g":"ai","word":"Savarankiškumas","text":"Kiek AI gali atlikti pats, kol privalo paklausti žmogaus.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Žmogaus dalyvavimas procese","text":"Žmogus lieka įtrauktas, kad svarbiais momentais patikrintų ar patvirtintų AI veiksmus. AI-gile tai esi tu.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Apsaugos ribos","text":"Apribojimai ir patikrinimai, padedantys AI veikti saugiai, pavyzdžiui, patvirtinimas prieš viešą diegimą. Jie mažina klaidų riziką, bet jos nepanaikina.","also":["guardrail","apsaugos priemonė"]},{"id":"rag","g":"ai","word":"Paieška papildytas generavimas (RAG)","text":"AI leidžiama prieš atsakant ieškoti tavo dokumentuose, kad atsakymai remtųsi tavo faktais.","also":["RAG","retrieval augmented generation","paieška papildytas generavimas"]},{"id":"embedding","g":"ai","word":"Vektorinis įterpinys","text":"Teksto pavertimas jo prasmę atspindinčiu skaičių sąrašu, kad kompiuteris rastų panašią reikšmę turinčius dalykus.","also":["embeddings","vektoriniai įterpiniai"]},{"id":"vectordb","g":"ai","word":"Vektorinė duomenų bazė","text":"Duomenų bazė, skirta ieškoti tokiuose skaičių sąrašuose ir rasti panašios prasmės medžiagą.","also":["vector databases","vector store","vektorinė saugykla"]},{"id":"mcp","g":"ai","word":"Modelio konteksto protokolas (MCP)","text":"Bendras būdas prijungti įrankius ir duomenų šaltinius prie AI programėlių, kad AI galėtų jais naudotis.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatūra","text":"Nuostata, lemianti AI atsakymų įvairovę. Žema duoda pastovesnius, lengviau nuspėjamus atsakymus, aukšta – įvairesnius, bet nė viena negarantuoja teisingumo.","also":["model temperature","modelio temperatūra"],"noTip":1},{"id":"multimodal","g":"ai","word":"Daugiarūšis","text":"Galintis dirbti su kelių rūšių informacija, pavyzdžiui, tekstu, vaizdais ir garsu.","also":["multi-modal","multimodalus"]},{"id":"evals","g":"ai","word":"AI vertinimas (eval)","text":"Suplanuotas AI gebėjimų patikrinimas pasirinktais pavyzdžiais, leidžiantis palyginti modelius ar užklausas.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Šališkumas","text":"Kai AI ar žmogus nepagrįstai palaiko vieną pusę, dažnai dėl to, iš ko mokėsi.","also":["biased","šališkas"],"noTip":1},{"id":"responsible","g":"ai","word":"Atsakingas AI","text":"Sąžiningas, saugus ir teisingas AI naudojimas, žmonėms išliekant atsakingiems už rezultatus.","also":["ethical AI","etiškas AI","etiškas DI"]},{"id":"injection","g":"ai","word":"Nurodymų įterpimo ataka","text":"Apgaulė, kai tinklalapyje ar faile paslėptais nurodymais bandoma priversti AI atlikti tai, ko naudotojas neprašė.","also":["prompt injections","nurodymų įterpimo atakos"]},{"id":"ratelimit","g":"ai","word":"Užklausų dažnio riba","text":"Riba, kiek užklausų per nustatytą laiką gali siųsti paslaugai. Ją viršijus reikia palaukti.","also":["rate limits","rate limited","dažnio ribojimas"]},{"id":"usagelimit","g":"ai","word":"Naudojimo riba","text":"Kiek AI darbo tavo planas leidžia per laikotarpį; po to darbas pristabdomas arba kainuoja daugiau.","also":["usage limits","naudojimo ribos"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Programų kūrimas daugiausia aiškinant AI, ko nori, ir leidžiant jam rašyti kodą.","also":["vibe-coding","programavimas aprašant norus"]},{"id":"budget","g":"money","word":"Biudžetas","text":"Pinigų suma, skirta konkrečiam tikslui.","also":["budgets","biudžetai"],"noTip":1},{"id":"costest","g":"money","word":"Išlaidų įvertis","text":"Apytikris spėjimas prieš pradedant, kiek kas nors kainuos.","also":["cost estimates","išlaidų įverčiai"]},{"id":"roi","g":"money","word":"Investicijų grąža (ROI)","text":"Ką gauni, palyginti su tuo, ką įdėjai. Jei grąža teigiama, investicija atsipirko.","also":["ROI"]},{"id":"tco","g":"money","word":"Bendroji nuosavybės kaina (TCO)","text":"Kiek kas nors iš tikrųjų kainuoja per visą savo gyvavimo laiką, ne tik pirkimo kaina: naudojimas, pagalba, atnaujinimai ir galiausiai atsisakymas.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx ir OpEx","text":"CapEx – išankstinės išlaidos ilgiau naudojamiems dalykams. OpEx – nuolatinės išlaidos, pavyzdžiui, mėnesinės sąskaitos.","also":["CapEx","OpEx","capital expenditure","operating expenditure","kapitalo išlaidos","veiklos išlaidos"]},{"id":"subscription","g":"money","word":"Prenumerata","text":"Reguliarus mokėjimas, paprastai kas mėnesį ar metus, kad galėtum toliau kuo nors naudotis.","also":["subscriptions","prenumeratos"],"noTip":1},{"id":"saas","g":"money","word":"Programinė įranga kaip paslauga (SaaS)","text":"Programinė įranga, kuria naudojiesi internetu ir už kurią moki prenumeratą, o jos veikimu rūpinasi kūrėjas.","also":["SaaS"]},{"id":"payg","g":"money","word":"Mokėjimas pagal naudojimą","text":"Mokėjimas tik už tai, ką sunaudoji, pavyzdžiui, debesijos išteklius ar AI žetonus.","also":["pay-as-you-go","usage-based pricing","kainodara pagal naudojimą"]},{"id":"overage","g":"money","word":"Viršytas naudojimas","text":"Naudojimas virš tavo plano ribų, už kurį gali reikėti mokėti papildomai.","also":["overages","overage charges","mokestis už viršijimą"]},{"id":"billingalert","g":"money","word":"Išlaidų įspėjimas","text":"Pranešimas, kai išlaidos ar naudojimas pasiekia pasirinktą ribą. Jis įspėja, bet ne visada sustabdo tolesnius mokesčius.","also":["billing alerts","spending alert","išlaidų įspėjimai"]},{"id":"freetier","g":"money","word":"Nemokamas planas","text":"Nemokamas mokamos paslaugos lygis su apribojimais. Patogu pradžiai.","also":["free plan","nemokamas planas"]},{"id":"pricing","g":"money","word":"Kainodaros planas","text":"Skirtingi paslaugos siūlomi paketai, kiekvienas su savo kaina ir ribomis.","also":["pricing plans","price plan","kainodaros planai"]},{"id":"licence","g":"money","word":"Licencija","text":"Taisyklės, kaip gali naudoti, kopijuoti, keisti ar platinti kito sukurtą dalyką, pavyzdžiui, programą, šriftą ar paveikslėlį.","also":["licences","license","licenses","licencijos"],"noTip":1},{"id":"opensource","g":"money","word":"Atvirasis kodas","text":"Programinė įranga, kurios kodą kiekvienas gali skaityti, naudoti ir dažnai nemokamai keisti pagal licencijos taisykles.","also":["open-source","open source software","OSS","atvirojo kodo programinė įranga"]},{"id":"osslicence","g":"money","word":"Atvirojo kodo licencija","text":"Taisyklės, taikomos atvirajam kodui. Vienos leidžia beveik viską, kaip MIT, kitos prašo dalytis ir pakeitimais, kaip GPL.","also":["open source licences","MIT licence","GPL","atvirojo kodo licencijos"]},{"id":"proprietary","g":"money","word":"Nuosavybinė programinė įranga","text":"Priklauso įmonei, todėl negalima laisvai kopijuoti ar keisti. Atvirojo kodo priešingybė.","also":["proprietary software","nuosavybinė programinė įranga"]},{"id":"copyright","g":"money","word":"Autorių teisės","text":"Įstatymo suteikta kūrėjo teisė kontroliuoti savo kūrinio, taip pat kodo ir tekstų, kopijavimą.","also":["copyrighted","saugoma autorių teisių"],"noTip":1},{"id":"ip","g":"money","word":"Intelektinė nuosavybė (IP)","text":"Idėjos ir kūriniai, kuriuos teisė laiko nuosavybe, pavyzdžiui, kodas, dizainas, pavadinimai ir logotipai.","also":["intellectual property","intelektinė nuosavybė"]},{"id":"tos","g":"money","word":"Paslaugos teikimo sąlygos","text":"Taisyklės, su kuriomis sutinki, kai naudojiesi paslauga.","also":["terms and conditions","terms of use","naudojimo sąlygos"]},{"id":"contract","g":"money","word":"Sutartis","text":"Rašytinis dviejų šalių susitarimas, kurio vykdymą užtikrina teisė.","also":["contracts","sutartys"],"noTip":1},{"id":"sow","g":"money","word":"Darbų aprašas (SOW)","text":"Dokumentas, tiksliai nustatantis, kokie darbai bus atlikti, iki kada ir už kiek.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fiksuota kaina","text":"Sutarta viso darbo kaina, nepriklausanti nuo jo trukmės.","also":["fixed-price","fiksuota kaina"]},{"id":"tm","g":"money","word":"Laikas ir medžiagos","text":"Mokėjimas už iš tikrųjų dirbtas valandas ir sunaudotas medžiagas, o ne nustatyta bendra kaina.","also":["T&M"]},{"id":"invoice","g":"money","word":"Sąskaita faktūra","text":"Dokumentas, kuriuo prašoma sumokėti už atliktą darbą ar pristatytas prekes.","also":["invoices","sąskaitos faktūros"],"noTip":1},{"id":"lockin","g":"money","word":"Priklausomybė nuo tiekėjo","text":"Kai pakeisti tiekėją taip sunku ar brangu, kad tenka su juo ir likti.","also":["lock-in","pririšimas prie tiekėjo"]},{"id":"procurement","g":"money","word":"Pirkimai","text":"Tiekėjų pasirinkimo ir pirkimo iš jų procesas.","also":["pirkimas"]},{"id":"servicecredit","g":"money","word":"Kompensacija už paslaugą","text":"Grąžinti pinigai ar nuolaida, gaunama tiekėjui neįvykdžius SLA.","also":["service credits","kompensacijos už paslaugą"]}]}};
